(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["video"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-phased-one-step-adversarial-equilibr-2025"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-1\">一 · 一个真实在线服务现场的账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-2\">二 · 多步教师与常规单步蒸馏的痛点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-3\">三 · 长视频与高分辨率下的显存与带宽双重挤压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-4\">四 · 为什么“把步数压到一步”不是免费的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-5\">五 · 分阶段均衡要解决的正是旧栈的均衡缺口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-6\">六 · 单步蒸馏的边界：为什么“一步出片”在线上会失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-7\">七 · 请求形态：帧数×分辨率×时长构成的三维负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-8\">八 · 并发与批大小：显存档位驱动的动态批调度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-9\">九 · SLO 与长尾：片段时延与端到端时延的两级口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-10\">十 · 负载塑造方案：分块长度与重叠的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-11\">十一 · 方案反过来限制负载：准入与降级策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-12\">十二 · 测量口径清单与容量规划的保守估计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-13\">十三 · 单步方案在真实请求分布下的边界：分块、并发与 SLO 的相互挤压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-14\">十四 · 单步学生的 kernel 形态：为什么精度选择先于算子选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-15\">十五 · 数据类型分层：FP16/BF16 作基准、FP8 作吞吐档、NVFP4 作探索档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-16\">十六 · 累加精度与误差传播：单步前向没有“下一步”来纠错</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-17\">十七 · Blackwell 特性如何改变单步学生的算子切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-18\">十八 · 精度与分块、批调度的耦合：把数值决策写进容量规划</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-19\">十九 · 工程判断：先固定累加精度，再逐层放开操作数精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-20\">二十 · 单步前向的显存与数值边界：分块、融合与量化验证</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-21\">二十一 · 单步之后，显存账本的重心转移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-22\">二十二 · 分块重叠：显存峰值的真正旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-23\">二十三 · KV 与缓存复用：单步场景下还剩什么可缓存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-24\">二十四 · 带宽瓶颈：HBM3e 容量与单步的带宽账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-25\">二十五 · 卸载与失败模式：账本要留余量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-26\">二十六 · 单步采样之后的真实账本：显存峰值、带宽瓶颈与分块边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-27\">二十七 · 单步前向把调度问题从“步数”搬到“片段”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-28\">二十八 · 连续批处理在片段粒度上的重组</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-29\">二十九 · Chunked prefill 的对应物：分块前向与解码流水</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-30\">三十 · 优先级、抢占与尾延迟的压制</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-31\">三十一 · 分离式预填/解码在单步视频上的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-32\">三十二 · 容量规划：按分块与批大小做保守估计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-33\">三十三 · 单步采样下的调度边界：分块、批与尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-34\">三十四 · 并行拓扑与单步学生的映射关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-35\">三十五 · NVLink 5 与 NVSwitch：集合通信的物理底座</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-36\">三十六 · NIXL 传输与分离式部署的接缝</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-37\">三十七 · 通信何时成为瓶颈：三个判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-38\">三十八 · 与分阶段均衡机制的耦合点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-39\">三十九 · 单步前向下的通信边界：并行拓扑何时失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-40\">四十 · 精度塌陷：单步学生的分布漂移如何被观测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-41\">四十一 · OOM 与显存峰值：分块长度是唯一硬旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-42\">四十二 · 批抖动与尾延迟：流式输出的片段顺序约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-43\">四十三 · 静默降级：量化与融合接缝的无声失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-44\">四十四 · 回滚路径：按阶段与配置分层的最小回退</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-45\">四十五 · 分块接缝、显存峰值与量化退化：三类失效的定位与回滚</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-46\">四十六 · 基准口径的三层结构：模型档、硬件档、负载档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-47\">四十七 · 指标集合：TTFT、TPOT、吞吐、显存、功耗各自度量什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-48\">四十八 · 数字怎么读：四类不可比的“提升”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-49\">四十九 · 容量规划的保守估计方法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-50\">五十 · 监控与失败模式对应的口径校验</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-51\">五十一 · 单步收益的边界：显存峰值、融合接缝与量化盲区</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-52\">五十二 · 迁移到非视频扩散主干：判别器语义先于权重迁移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-53\">五十三 · 跨领域迁移的改动清单：三个必须重设的量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-54\">五十四 · 哪里不适用：单步假设失效的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-55\">五十五 · 规模上限：分块、批与显存三者的耦合约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-56\">五十六 · 工程判断：迁移前先证明三件事</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-phased-one-step-adversarial-equilibr-2025-sec-57\">五十七 · 迁移边界：单步学生换到别的模型要先改什么</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:584px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 584.1 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入后按分辨率与帧数分块，长视频切分为带重叠的时空片段以控制单次前…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">教师多步采样生成参考轨迹，学生单步前向在相同初始噪声下生成候选视频。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">判别器在多阶段目标下比较学生输出与教师输出，维持对抗均衡并更新学生。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">学生单步输出经 VAE 解码为像素视频，分块结果按重叠区域融合为长视频。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">批量与流式输出按片段调度，显存不足时降低批大小或缩短分块长度。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-1\">一 · 一个真实在线服务现场的账本</h3>\n<p>设想一个短视频平台的文生视频接口：用户在编辑器里改一句提示词，期望几秒内看到 4 秒、720p 的预览片段，满意后再排队出高分辨率成片。请求到达调度器后，先按帧数与分辨率切分成带重叠的时空片段，每个片段走一遍扩散采样，再经 VAE 解码为像素、按重叠权重融合。这条链路在 Blackwell 档位上的成本结构非常具体：采样步数决定单次请求的算力总量，分块长度决定单次前向的显存峰值，VAE 解码缓冲决定解码阶段的驻留显存，而流式返回要求片段按顺序产出，端到端时延由最慢片段而非平均片段决定。</p>\n<p>旧方案在这里的账本是：教师模型需要数十步采样才能达到可接受质量，推理成本随步数线性增长。若一步前向的时空注意力激活与 VAE 解码缓冲合计占用显存为 M，则单请求显存峰值近似为</p>\n<div class=\"formula\">$$M_{\\text{peak}} \\approx M_{\\text{attn}}(T,H,W,b) + M_{\\text{vae}}(T,H,W) + M_{\\text{block}}$$</div>\n<p>其中 T、H、W 为片段帧数与空间尺寸，b 为批大小。步数 S 不直接进入显存峰值，但它线性放大算力与带宽占用：每步都要重读权重、重算注意力、重写潜变量。对在线服务而言，这意味着单卡并发被压到很低，队列等待时间随负载抖动，SLO 只能靠堆卡维持。工程上非改不可的理由不是“步数多不好看”，而是步数把单位请求的算力预算锁死，使分块长度与批大小两个可调旋钮都失去腾挪空间。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-2\">二 · 多步教师与常规单步蒸馏的痛点</h3>\n<p>旧栈的主流做法有两条。第一条是直接跑多步教师采样：质量有保证，但每个片段要串行执行数十次前向，时空注意力在每一帧、每一对帧之间反复激活。对长视频而言，分块是必须的，因为不分块的单次前向显存峰值会直接顶到卡的上限；分块又带来接缝融合的额外开销与闪烁风险。第二条是常规单步蒸馏：用一个学生网络一次前向匹配教师多步采样的结果，把采样步数从数十步压到一步。这条路线在图像上已有实践，但搬到视频扩散上，问题集中在对抗目标下的训练不稳定。</p>\n<p>常规单步蒸馏的损失通常是蒸馏损失加对抗损失的加权组合，判别器比较学生输出与教师输出。问题在于：单步学生要在一次前向里覆盖教师数十步的分布，其输出分布与教师分布的差距在训练初期很大；判别器一旦过强，学生梯度被对抗项主导，容易出现模式崩溃——生成结果塌缩到少数几种运动模式，复杂运动与长时序细节丢失。判别器过弱则学生学不到教师的分布形状。教师与学生的分布均衡难以维持，训练曲线在崩溃与欠拟合之间摆动。对推理栈的直接影响是：学生不可靠，线上不敢用单步，只能退回多步教师，步数红利拿不到。</p>\n<p>代价可以定性表述：训练不稳定意味着需要更多训练轮次与人工调参，训练开销上升；推理侧不敢启用单步，采样步数维持在高位，单请求算力与带宽占用不降；分块长度被迫保守，批大小上不去，吞吐被显存峰值卡住。这三者叠加，使“少步推理加速”的承诺在工程上无法兑现。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-3\">三 · 长视频与高分辨率下的显存与带宽双重挤压</h3>\n<p>视频扩散的显存压力不只来自采样步数，更来自时空注意力的激活规模与 VAE 解码缓冲。以带重叠的时空片段为单位，单次前向的注意力激活随片段帧数与空间分辨率增长，VAE 解码阶段还要为像素重建保留缓冲。旧方案在多步采样下，每一步都要重新分配与读写这些激活，带宽占用随步数线性累积；在 B200/GB200 NVL72 这类档位上，HBM 带宽是稀缺资源，多步采样把带宽预算消耗在重复读写上，而不是有效计算。</p>\n<p>分块是旧栈的默认应对：把长视频切成带重叠的片段，逐段采样再融合。分块长度直接决定单次前向显存峰值，缩短分块能降峰值，但重叠区域变多、融合开销上升、接缝闪烁风险增加；放长分块则峰值顶到卡上限，批大小只能降到 1，吞吐塌陷。批调度按片段长度与显存档位调整批大小，显存不足时降低并发或缩短分块——这是旧栈的常规操作，但它是在多步采样的高基数成本上做减法，腾挪空间有限。流式输出按片段顺序返回，片段生成时延与端到端视频时延共同构成 SLO，而多步采样让片段时延难以压缩。</p>\n<p>具体例子：一个 4 秒、720p 的请求被切成若干带重叠片段，每段走数十步采样。若单段单步前向的注意力激活与解码缓冲已接近显存档位的一半，则批大小只能取小值，多步采样下每段耗时被步数放大，端到端时延由片段数乘以单段时延决定。此时即便增加卡数，单请求时延也不会改善，因为它是串行步数与串行片段的乘积。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-4\">四 · 为什么“把步数压到一步”不是免费的</h3>\n<p>单步学生前向替代多步迭代，采样步数从数十步降到一步，算力与带宽的线性放大项消失，这是该论文的核心杠杆。但代价发生转移：主要成本从“步数乘以每步开销”转移到“单步内的时空注意力激活与 VAE 解码缓冲”。单步前向仍要一次性处理整个片段的时空注意力，激活峰值不因步数减少而下降；VAE 解码仍要为像素重建保留缓冲。因此单步化降低的是时间维度上的累积成本，不降低单次前向的空间峰值。工程判断必须把这两笔账分开：吞吐与端到端时延受益于步数下降，显存峰值与分块长度仍受单步前向的激活规模约束。</p>\n<p>更棘手的是数值精度。材料未给出 NVFP4/FP8 精度下的数值稳定性与显存收益数据，而单步学生在强对抗训练后对数值扰动更敏感：一次前向要覆盖教师多步的分布，量化误差在时空注意力与 VAE 解码两处都可能放大。未验证量化稳定性就上线，可能出现单步学生输出退化，表现为运动细节丢失或接缝处异常。部署前需补量化验证与失败模式监控，这是旧栈没有暴露、单步化之后才成为一等公民的风险项。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-5\">五 · 分阶段均衡要解决的正是旧栈的均衡缺口</h3>\n<p>旧栈的均衡缺口在于：判别器强度是一个全局超参，训练全程固定或粗调，无法同时满足训练初期“别把学生压崩”和训练后期“把分布收紧”两个相反需求。该论文的方案是把单步对抗蒸馏拆成多个阶段，每个阶段固定判别器强度训练学生若干步，再进入下一阶段收紧判别目标；阶段间共享学生权重，判别器重置以维持教师与学生的分布均衡。目标函数仍是蒸馏损失与对抗损失的加权组合：</p>\n<div class=\"formula\">$$\\min_{G}\\max_{D}\\ \\mathbb{E}_{x\\sim p_{data}}\\left[\\log D(x)\\right]+\\mathbb{E}_{z\\sim p_{z}}\\left[\\log\\left(1-D\\left(G_{\\theta}(z)\\right)\\right)\\right]+\\lambda\\,\\mathcal{L}_{\\text{distill}}\\left(G_{\\theta}(z),\\,G_{\\text{teacher}}(z)\\right)$$</div>\n<p>分阶段的作用是让判别器强度成为随训练进程变化的量，而不是一次性押注。学生在每个阶段内面对固定的对抗压力，避免在强对抗下直接模式崩溃；阶段切换时重置判别器，防止判别器记住上一阶段的学生输出而过早饱和。对推理栈的意义是：单步学生变得可用，采样步数从数十步降到一步，单请求算力与带宽占用下降，分块长度与批大小重新获得腾挪空间。具体阶段数、损失权重与训练步数材料未给出，工程落地只能按阶段划分与对抗权重作为主要变量做保守配置。</p>\n<p>代价方面，分阶段训练增加训练开销，判别器均衡对超参敏感；推理侧的单步前向把显存主要压在时空注意力激活与 VAE 解码缓冲上，批调度仍需按片段长度与显存档位调整批大小，显存不足时缩短分块或降低并发。流式输出按片段顺序返回，监控需关注分块融合接缝、显存峰值与片段时延，失败时降批或缩短分块。这些机制与代价构成本篇后续拆解的对象：分阶段如何落到训练循环、单步前向如何在 Blackwell 上配置分块与批大小、量化验证如何补齐。</p>\n\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-6\">六 · 单步蒸馏的边界：为什么“一步出片”在线上会失效</h3>\n<p>设想一个短视频平台的生成接口：用户提交一段 720p、数秒长的提示词，SLO 要求首帧在数百毫秒内返回、整段视频在秒级完成。若沿用多步教师采样，采样步数与延迟近似线性：<div class=\"formula\">$$T_{\\text{e2e}} \\approx N_{\\text{step}}\\cdot t_{\\text{denoise}} + t_{\\text{vae}} + t_{\\text{merge}}$$</div>步数从数十步压到一步，理论上把第一项削掉一个数量级。但线上真正卡住的往往不是去噪循环本身，而是单步前向把全部计算压进一次时空注意力，激活峰值与 VAE 解码缓冲同时抬升——步数减少不等于显存减少，这是旧方案最容易被误判的地方。</p>\n<p>旧栈的主流做法是“多步教师 + 常规单步蒸馏”：教师用多步采样生成参考轨迹，学生用一次前向在相同初始噪声下回归教师输出，损失以蒸馏项为主。问题在于，纯回归目标把学生拉向教师轨迹的均值，缺乏对抗信号时细节塌陷；一旦加入判别器，单步学生又在强对抗下模式崩溃，教师与学生分布偏离，训练不稳定。分阶段方案正是针对这一失效条件：每个阶段固定判别器强度训练学生若干步，阶段间共享学生权重、重置判别目标，逐步收紧而非一次性压到最强。代价是训练侧多出若干阶段的开销，且阶段数与损失权重材料未给出，超参敏感度无法从论文直接读出。</p>\n<p>推理侧的代价结构需要重新算账。长视频按帧数与分辨率切成带重叠的时空片段，单步学生逐片段前向，重叠区按权重融合。分块长度直接决定单次前向的显存峰值：片段越长，时空注意力激活越大，VAE 解码缓冲也越大；批大小则受显存档位约束，显存不足时只能降并发或缩短分块，两者都直接吃吞吐。下表给出旧多步栈与单步分块栈的代价对照（定性，论文未给数字）：</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>多步教师采样</th><th>单步分块栈</th></tr></thead><tbody><tr><td>采样步数</td><td>数十步迭代</td><td>一步前向</td></tr><tr><td>延迟主项</td><td>步数×去噪</td><td>时空注意力激活 + VAE 解码</td></tr><tr><td>显存峰值</td><td>随步数累积的中间激活</td><td>由分块长度与批大小决定</td></tr><tr><td>失效模式</td><td>延迟不可压</td><td>接缝闪烁、单步细节退化</td></tr></tbody></table>\n<p>边界条件因此很清楚：单步收益只在“分块长度可控、VAE 解码不成为瓶颈、数值精度已验证”三者同时成立时兑现。重叠融合不当会在接缝处产生闪烁，需按重叠权重与片段顺序校验；未验证 NVFP4/FP8 数值稳定性就上线，单步学生输出可能退化，而论文未给出该精度下的稳定性与显存收益数据。容量规划只能按分块与批大小做保守估计，监控需盯住分块融合接缝、显存峰值与片段时延，失败时降批或缩短分块——这是把单步蒸馏从训练指标落到 Blackwell 部署时必须先付的工程账。</p>\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-7\">七 · 请求形态：帧数×分辨率×时长构成的三维负载</h3>\n<p>视频扩散推理的请求不是标量长度，而是一个三维张量：帧数 <em>F</em>、分辨率 <em>H×W</em>、以及由文本提示隐含的时长语义。对单步学生而言，这三者共同决定单次前向的激活规模。时空注意力激活近似正比于 <em>F·H·W</em> 的平方项（空间注意力）与线性项（时间注意力）之和，VAE 解码缓冲则正比于 <em>F·H·W·C</em>（<em>C</em> 为潜变量通道数）。因此请求长度分布不能只按“秒数”统计，必须按 <em>(F, H, W)</em> 三元组分桶。</p>\n<p>工程上可核查的口径是：在服务入口记录每个请求的 <em>F</em>、<em>H</em>、<em>W</em>、提示词 token 数，并按 <em>F·H·W</em> 分位数（p50/p90/p99）统计。分块策略把长视频切成带重叠的时空片段，片段长度 <em>L<sub>chunk</sub></em> 直接决定单次前向显存峰值；重叠帧数 <em>O</em> 决定融合接缝的平滑度，也决定有效计算量放大系数 <em>(L<sub>chunk</sub>+O)/L<sub>chunk</sub></em>。举例：一个 720p、121 帧的请求，若按 33 帧分块、重叠 4 帧，则需 4 个片段，有效计算量放大约 1.12 倍，显存峰值由单片段而非整段决定——这正是单步方案能把长视频塞进 B200 单卡显存档位的机制来源。</p>\n<div class=\"formula\">$$M_{\\text{peak}} \\approx \\alpha \\cdot L_{\\text{chunk}} \\cdot H \\cdot W + \\beta \\cdot L_{\\text{chunk}} \\cdot H \\cdot W \\cdot C_{\\text{vae}}$$</div>\n<p>代价落在显存与带宽两侧：时空注意力激活走 HBM 读写，VAE 解码缓冲走片上与 HBM 之间的搬运。单步采样把步数从数十降到一，采样侧的计算与激活累积消失，但 VAE 解码缓冲不随步数缩减，成为新的显存下限。这是负载塑造方案的第一个约束：分块长度不能只按注意力激活定，还要给 VAE 解码留出缓冲。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-8\">八 · 并发与批大小：显存档位驱动的动态批调度</h3>\n<p>单步学生的批调度与多步教师有本质差异。多步采样时，批内每个样本要迭代数十次，激活在时间维度上反复复用，批大小受限于单步激活乘以步数后的峰值；单步前向只做一次，激活峰值等于单次前向，批大小可以更大，但 VAE 解码缓冲随批线性增长。因此批大小 <em>B</em> 的可行域由下式约束：</p>\n<div class=\"formula\">$$B \\le \\left\\lfloor \\frac{M_{\\text{budget}} - M_{\\text{static}}}{M_{\\text{attn}}(L_{\\text{chunk}}) + M_{\\text{vae}}(L_{\\text{chunk}})} \\right\\rfloor$$</div>\n<p>其中 <em>M<sub>static</sub></em> 是权重与常驻缓冲，<em>M<sub>attn</sub></em> 与 <em>M<sub>vae</sub></em> 分别是单样本的注意力激活与解码缓冲。批调度按片段长度与显存档位动态调整：显存不足时先降并发，再缩短分块。这里的工程判断是降并发优先于缩分块——缩短分块会增加片段数与重叠开销，反而抬高总计算量；降并发只影响吞吐，不改变单请求的端到端时延结构。</p>\n<p>可核查口径：记录每个调度周期的 <em>B</em>、<em>L<sub>chunk</sub></em>、显存峰值占用量、以及因显存不足触发的降级次数。降级次数是容量规划的关键指标，它反映请求形态分布与显存档位之间的错配程度。举例：若 p99 请求的 <em>F·H·W</em> 是 p50 的 4 倍，而批调度只按平均长度配置，则 p99 请求会频繁触发降级，表现为长尾时延抬升——这不是模型慢，是调度策略与负载分布不匹配。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-9\">九 · SLO 与长尾：片段时延与端到端时延的两级口径</h3>\n<p>视频请求的 SLO 必须分两级：片段生成时延与端到端视频时延。流式输出按片段顺序返回，用户感知的是首片段时延与片段间间隔，而非整段完成时间。单步方案把每片段的前向压到一次，片段时延主要由时空注意力与 VAE 解码构成；端到端时延则是片段数乘以片段时延再加上融合开销。长尾来自两个方向：超长请求的片段数多，端到端时延线性拉长；超高分辨率请求的单片段显存峰值高，触发降批或缩分块，片段时延抬升。</p>\n<p>可核查口径：分别统计首片段时延（TTFF，time to first frame）、片段间隔（inter-chunk gap）、端到端时延（E2E）的 p50/p90/p99，并按 <em>F·H·W</em> 分桶交叉统计。SLO 应定义在分桶后的 p99 上，而非全局平均。举例：若 SLO 要求 720p、5 秒视频在 8 秒内返回，则片段时延预算约为 8 秒除以片段数再减去融合开销；单步前向若占片段时延的主要部分，则 VAE 解码的优化优先级不低于注意力核。</p>\n<p>代价侧：长尾请求占用显存档位的时间更长，等效并发下降。容量规划需按分桶后的到达率与驻留时间估算所需副本数，而非按平均请求。这是负载反过来限制方案的典型场景：SLO 收紧会迫使分块更细、批更小，吞吐下降；吞吐目标抬高又会放宽 SLO 分桶，长尾被牺牲。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-10\">十 · 负载塑造方案：分块长度与重叠的取舍</h3>\n<p>分块长度不是自由参数，它被请求形态分布与显存档位共同夹住。分块过长，单片段显存峰值超预算，触发降级；分块过短，片段数增多，重叠开销与融合接缝增多，端到端时延与画质风险同时上升。重叠帧数 <em>O</em> 的取舍同理：<em>O</em> 太小，接缝处闪烁；<em>O</em> 太大，有效计算量放大。可核查口径是接缝处的帧间一致性指标与重叠区域融合权重的一致性校验，配合显存峰值与片段时延记录。</p>\n<p>单步学生在这里有一个结构性优势：多步教师的分块必须在步数维度上保持片段间的一致性（否则步间漂移会在接缝处放大），而单步前向没有步间漂移，接缝问题退化为片段边界处的条件不一致，融合权重的作用更直接。举例：同一提示词下相邻片段以相同初始噪声与重叠帧条件生成，重叠区域按线性权重融合，接缝闪烁的根因从“步间漂移”变为“片段边界条件差异”，监控口径也应相应调整。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-11\">十一 · 方案反过来限制负载：准入与降级策略</h3>\n<p>推理方案一旦定下分块长度与显存档位，就反过来定义了可接纳的请求形态。准入控制需按 <em>(F, H, W)</em> 三元组判断是否超出单片段显存预算，超出则拒绝或排队至低峰，而非静默降级。降级策略要显式：缩分块、降批、降分辨率三选一，且每次降级都记录原因与影响面。这里的工程判断是：静默降级会让长尾时延不可解释，监控口径必须把降级事件与请求 ID 关联。</p>\n<p>可核查口径包括：准入拒绝率按分桶统计、降级事件率、降级后片段时延与画质指标（接缝一致性、帧间稳定性）。失败模式中“把单步蒸馏收益直接等同于吞吐提升”正对应此处——单步降低了采样侧计算，但若准入与降级策略未随负载形态调整，显存峰值与 VAE 解码缓冲会把吞吐收益吃掉。另一个失败模式是未验证 NVFP4/FP8 数值稳定性即上线，单步学生在低精度下的输出退化会表现为画质指标异常，需在降级监控中单列。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-12\">十二 · 测量口径清单与容量规划的保守估计</h3>\n<p>把上述口径收敛为可执行清单：请求侧记录 <em>F</em>、<em>H</em>、<em>W</em>、提示词 token 数、到达时间；调度侧记录 <em>B</em>、<em>L<sub>chunk</sub></em>、<em>O</em>、显存峰值、降级事件；时延侧记录 TTFF、片段间隔、E2E 的分桶分位数；画质侧记录接缝一致性与帧间稳定性。四类记录按请求 ID 关联，才能把“负载形态—方案参数—代价”三者对上。</p>\n<p>容量规划在材料未给出吞吐与 FVD 数字的前提下只能做保守估计：以单片段显存峰值为硬约束反推最大并发，以片段数与片段时延估算 E2E 下界，再按分桶到达率留出长尾余量。可核查的保守系数来自重叠放大 <em>(L<sub>chunk</sub>+O)/L<sub>chunk</sub></em> 与降级触发率的历史统计。举例：若降级触发率在 p99 分桶上持续高于阈值，说明分块长度与显存档位错配，应优先调分块而非加副本——加副本只稀释并发压力，不解决单请求的显存峰值问题。最后落在具体机制上：分阶段对抗均衡改变的是学生分布与教师分布的逼近程度，而请求形态与批调度改变的是这份逼近能否在显存档位内稳定兑现；两者在容量规划里必须分开核算，混在一起会把训练侧的均衡收益误记为推理侧的吞吐收益。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-13\">十三 · 单步方案在真实请求分布下的边界：分块、并发与 SLO 的相互挤压</h3>\n\n<p>单步学生把采样步数从数十步压到一步，收益并不均匀落在所有请求上。请求按帧数与分辨率切分为带重叠的时空片段后，单次前向的显存峰值由分块长度直接决定，而分块长度又受限于 B200/B300 单卡或 GB200 NVL72 单节点的显存档位。设片段帧数为 <span class=\"formula-inline\">$F$</span>、空间分辨率为 <span class=\"formula-inline\">$H\\times W$</span>、潜变量通道为 <span class=\"formula-inline\">$C$</span>，则单片段激活量近似正比于 <span class=\"formula-inline\">$F\\cdot H\\cdot W\\cdot C$</span> 与时空注意力窗口的乘积；批大小 <span class=\"formula-inline\">$B$</span> 再线性放大该峰值。于是可行批大小满足</p>\n\n<div class=\"formula\">$$B \\le \\left\\lfloor \\frac{M_{\\text{budget}} - M_{\\text{VAE}} - M_{\\text{weight}}}{M_{\\text{act}}(F,H,W)} \\right\\rfloor$$</div>\n\n<p>其中 <span class=\"formula-inline\">$M_{\\text{VAE}}$</span> 是解码缓冲，<span class=\"formula-inline\">$M_{\\text{act}}$</span> 是单片段时空注意力激活。这个不等式说明：长视频请求不是靠调大并发解决的，而是靠缩短分块或降低并发换显存。工程上必须把“分块长度”和“批大小”作为一对联合调度变量，而不是各自独立配置。失效条件很具体——当请求的帧数分布长尾很重、少数超长请求把分块推到显存上限时，批大小被迫降到 1，此时单步采样省下的计算时间会被 VAE 解码与逐片段串行化吃掉，端到端时延反而由片段数量而非步数决定。</p>\n\n<p>负载形态对方案的塑造体现在 SLO 口径上。流式输出按片段顺序返回，因此可核查的指标必须拆成两级：片段级首帧时延（从分块前向开始到该片段 VAE 解码完成）与端到端视频时延（从请求进入到末片段融合返回）。若只报端到端时延，会掩盖长尾请求中分块串行导致的尾部放大；若只报片段时延，则忽略重叠区域按权重融合带来的额外后处理开销。容量规划应按分块长度与批大小做保守估计，因为论文未给出数据集、FVD、吞吐与端到端时延数字，任何把单步收益直接折算成 QPS 提升的做法都缺少可核验依据。反过来，方案也限制负载：分块重叠比例越高，接缝闪烁风险越低，但融合计算与显存占用上升；重叠比例越低，吞吐越好，却把风险推给质量监控。</p>\n\n<table class=\"mini\"><thead><tr><th>测量口径</th><th>观测量</th><th>失效信号</th></tr></thead><tbody><tr><td>片段级首帧时延</td><td>分块前向 + VAE 解码耗时</td><td>分块过长导致批大小塌到 1</td></tr><tr><td>端到端视频时延</td><td>末片段融合返回时刻</td><td>长尾请求片段串行放大</td></tr><tr><td>显存峰值</td><td>时空注意力激活 + 解码缓冲</td><td>降批或缩短分块触发</td></tr><tr><td>接缝质量</td><td>重叠区权重融合一致性</td><td>重叠比例过低产生闪烁</td></tr></tbody></table>\n\n<p>还有一层代价常被忽略：分阶段对抗蒸馏的均衡是在训练侧维持的，推理侧并不自带分布保证。单步学生在强对抗下存在模式崩溃风险，分阶段收紧判别目标是论文声称的缓解机制，但具体阶段数与权重材料未给出，因此部署侧只能用监控兜底——把重叠区融合一致性、片段间亮度/运动连续性作为在线信号，一旦退化就回退到更保守的分块与更低并发。量化同样如此：材料未给出 NVFP4/FP8 下单步学生的数值稳定性与显存收益数据，上线前必须在目标档位上验证单步前向输出是否退化，否则“省显存”的假设会在 VAE 解码缓冲处被反噬。最终判断落在调度器上：分块长度、批大小、重叠比例三者构成一个受显存与 SLO 双重约束的可行域，单步采样只是把可行域的一侧边界向外推，并不能消除边界本身。</p>\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-14\">十四 · 单步学生的 kernel 形态：为什么精度选择先于算子选择</h3>\n<p>分阶段单步对抗蒸馏把推理路径压缩成一次学生前向，但这并不意味着 kernel 工作量等比例缩小。学生网络内部仍要完成时空注意力、前馈层与 VAE 解码，其中时空注意力的激活规模随分块帧数与分辨率平方增长，VAE 解码缓冲则与像素片段尺寸线性相关。论文材料明确指出，单步采样把采样步数从数十步降到一步后，主要代价转移到时空注意力激活与 VAE 解码缓冲。这意味着精度决策的第一约束不是算力，而是显存与带宽：在 B200/GB200 NVL72 档位上，一次前向的激活峰值决定分块长度与批大小，而分块长度又反过来决定单次前向能否装进 HBM。</p>\n<p>把一次学生前向写成算子链：潜变量输入经 patchify 进入时空注意力块，注意力输出经 FFN 与残差归一化，最后送入 VAE 解码器。设分块含 <em>F</em> 帧、每帧 <em>H×W</em> 像素、潜空间下采样率为 <em>s</em>，则单次前向的注意力激活量近似为</p>\n<div class=\"formula\">$$M_{\\text{act}} \\approx b \\cdot F \\cdot \\left(\\frac{H}{s}\\right)\\left(\\frac{W}{s}\\right) \\cdot d \\cdot c_{\\text{bytes}}$$</div>\n<p>其中 <em>b</em> 为批大小，<em>d</em> 为 token 维度，<em>c</em><sub>bytes</sub> 为每个激活元素的字节数。FP16/BF16 下 <em>c</em><sub>bytes</sub>=2，FP8 下为 1，NVFP4 下为 0.5。公式逐项含义：<em>b·F·(H/s)(W/s)</em> 是 token 总数，乘 <em>d</em> 得到元素数，再乘字节宽度得到显存占用。工程判断很直接：把激活从 BF16 降到 FP8，同一显存档位下分块长度可翻倍，或批大小可翻倍；降到 NVFP4 则理论上有四倍余量，但单步学生没有多步迭代的误差平均效应，量化误差会直接进入输出分布。</p>\n<p>具体例子：一个 720p、49 帧的分块，潜空间 8 倍下采样后约 90×160 个 token/帧，乘 49 帧约 70 万 token，<em>d</em>=3072 时 BF16 激活约 4.3 GB 量级；若切到 FP8，同一分块激活降到约 2.1 GB，这正是能否在单卡 HBM 内放下注意力与 VAE 缓冲的分界。这里不引入实测数字，只说明量级关系决定分块策略。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-15\">十五 · 数据类型分层：FP16/BF16 作基准、FP8 作吞吐档、NVFP4 作探索档</h3>\n<p>论文材料未给出量化方案，也未给出 NVFP4/FP8 下的数值稳定性数据，因此本节的写法是把数据类型按“可验证性”分层，而不是宣称某档已被论文验证。基准档是 BF16：动态范围与 FP32 接近，适合作为单步学生的参考实现，因为对抗蒸馏的判别器梯度对激活异常值敏感，BF16 的指数位宽能容纳注意力 logits 的尖峰。FP16 精度更高但动态范围窄，在 VAE 解码的残差累加中更容易溢出，通常只在权重与部分激活上使用。</p>\n<p>FP8 分 E4M3 与 E5M2 两种格式：E4M3 尾数多、适合权重与激活的前向；E5M2 动态范围大、适合梯度。单步学生推理只走前向，因此 E4M3 是主选，配合 per-tensor 或 per-channel scaling。关键代价在缩放因子的选择：时空注意力的 QK^T 输出分布随分块内容变化，固定 scaling 会在高运动片段上截断，需要动态 scaling 或按头分组 scaling，这引入额外的归约与同步开销，抵消一部分 FP8 的吞吐收益。</p>\n<p>NVFP4 在 Blackwell 上以微块缩放（micro-block scaling）形式出现，每若干元素共享一个指数，尾数仅几位。对单步学生而言，NVFP4 的风险不对称：权重可以离线校准，激活却依赖输入，而单步生成没有后续步骤修正误差。论文材料明确要求部署前补 NVFP4/FP8 数值稳定性验证与失败模式监控，这说明量化收益无法从论文核验，只能作为探索档在分块融合接缝、显存峰值与片段时延三项监控下小流量试运行。</p>\n<table class=\"mini\"><thead><tr><th>档位</th><th>典型用途</th><th>主要代价</th><th>验证前提</th></tr></thead><tbody><tr><td>BF16</td><td>基准学生前向、判别器参考</td><td>激活显存为 FP8 两倍</td><td>无需额外校准</td></tr><tr><td>FP16</td><td>权重、VAE 部分层</td><td>残差累加溢出风险</td><td>逐层溢出检查</td></tr><tr><td>FP8 E4M3</td><td>注意力与 FFN 前向</td><td>动态 scaling 同步开销</td><td>按头分组 scaling 校验</td></tr><tr><td>NVFP4</td><td>权重与部分激活探索</td><td>单步无误差平均，分布偏移</td><td>接缝闪烁与输出退化监控</td></tr></tbody></table>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-16\">十六 · 累加精度与误差传播：单步前向没有“下一步”来纠错</h3>\n<p>多步采样中，每一步的量化误差会被后续步骤的随机性部分平滑；单步学生只有一次前向，误差直接映射到像素。因此累加精度的选择比数据类型本身更关键。矩阵乘的累加通常在 FP32 完成，Blackwell 第五代 Tensor Core 支持 FP32 累加器；若把累加降到 FP16，长 K 维的时空注意力与 FFN 会累积舍入误差，表现为低频色偏或运动拖影。工程上应保持 FP32 累加，仅压缩输入操作数，这是“输入低精度、累加高精度”的标准折中。</p>\n<p>误差传播可用一阶近似描述。设某层输入扰动为 <em>δx</em>，层雅可比为 <em>J</em>，则输出扰动 <em>δy ≈ J·δx</em>；沿 <em>L</em> 层链式传播后</p>\n<div class=\"formula\">$$\\|\\delta y_L\\| \\lesssim \\left(\\prod_{l=1}^{L}\\|J_l\\|\\right)\\|\\delta x\\|$$</div>\n<p>公式逐项：<em>‖J_l‖</em> 是第 <em>l</em> 层算子对输入的谱范数，乘积给出误差放大上界。注意力层的 softmax 雅可比在 logits 尖峰处范数偏大，FFN 的激活函数在饱和区雅可比偏小。单步学生的层数固定，乘积上界意味着量化误差最易在注意力块被放大，因此 FP8/NVFP4 应优先用于 FFN 与 VAE 解码器，注意力块保留 BF16 或采用更细的 scaling。代价是混合精度引入格式转换 kernel，在分块边界产生额外带宽往返；收益是避免接缝闪烁这一论文明确列出的失败模式。</p>\n<p>具体例子：若把 VAE 解码器的残差卷积降到 FP8 而累加保持 FP32，像素重建误差主要表现为高频细节损失；若把时空注意力的 QK^T 降到 NVFP4 且 scaling 粒度不足，误差表现为跨帧一致性下降，在重叠融合处形成可见接缝。两类误差的监控指标不同：前者看片段内 PSNR 类指标，后者看重叠区域的时间一致性。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-17\">十七 · Blackwell 特性如何改变单步学生的算子切分</h3>\n<p>tcgen05 是 Blackwell 的第五代 Tensor Core 指令族，配合 TMEM（Tensor Memory）把矩阵乘的累加器放在专用片上存储，减少寄存器压力与共享内存往返。对单步学生而言，这意味着注意力的大矩阵乘可以更长驻留在片上，分块长度不再被寄存器容量硬约束，而被 TMEM 容量与 HBM 带宽约束。工程含义是：同样显存档位下可以尝试更长的时空分块，减少重叠帧比例，从而降低融合接缝数量与总前向次数。</p>\n<p>2-SM MMA 让两个 SM 协同完成一次矩阵乘，把单个 MMA 的吞吐提高的同时要求数据布局与同步更严格。对批调度的影响是：批大小与分块长度需要对齐到 2-SM 的切分粒度，否则会出现一个 SM 空转的尾块。论文材料指出批调度按片段长度与显存档位调整批大小，显存不足时降低并发或缩短分块；在 2-SM 路径下，缩短分块应优先按 MMA 粒度对齐，而不是任意缩短，否则尾块浪费会抵消缩短带来的显存收益。</p>\n<p>代价侧要算清楚：tcgen05 与 TMEM 提升的是矩阵乘密度，但单步学生的主要瓶颈在时空注意力激活的写回与 VAE 解码缓冲的带宽。设 HBM 带宽为 <em>B</em>，单次前向需搬运的激活与权重总量为 <em>Q</em>，则带宽下界时间为 <em>T ≥ Q/B</em>；当 <em>Q</em> 中激活占主导时，提升 Tensor Core 利用率并不能等比例缩短端到端时延。这正是“把单步蒸馏收益直接等同于吞吐提升”这一失败模式的根源：算子密度提升被激活搬运掩盖。</p>\n<p>具体例子：一个带重叠的时空分块在 2-SM MMA 下若批大小未对齐，尾块使有效吞吐下降；把批大小对齐到 2 的倍数并保持 FP32 累加，可在不增加显存峰值的前提下减少尾块比例。这类对齐属于 kernel 层判断，不需要论文给出数字即可在部署侧验证。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-18\">十八 · 精度与分块、批调度的耦合：把数值决策写进容量规划</h3>\n<p>精度不是孤立开关，它通过显存峰值反向约束分块长度与批大小。把第一节的激活公式与分块策略联立：给定显存档位 <em>M</em><sub>budget</sub>，扣除 VAE 解码缓冲 <em>M</em><sub>vae</sub> 与权重 <em>M</em><sub>w</sub> 后，可用于注意力的余量为 <em>M</em><sub>act</sub>；由 <em>M</em><sub>act</sub> 解出允许的 token 总数，再按帧数与分辨率折算分块长度。降低 <em>c</em><sub>bytes</sub> 直接放大允许的分块长度，但若量化引入接缝闪烁，融合校验的额外开销会吃掉部分收益。</p>\n<div class=\"formula\">$$L_{\\text{chunk}} \\le \\frac{M_{\\text{budget}} - M_{\\text{vae}} - M_{\\text{w}}}{b \\cdot d \\cdot c_{\\text{bytes}} \\cdot \\left(\\frac{H}{s}\\right)\\left(\\frac{W}{s}\\right)}$$</div>\n<p>公式逐项：分子是可分配给注意力的显存，分母是每帧 token 的激活字节数乘以批大小，商给出允许帧数上界。工程上应把该上界与 2-SM MMA 的粒度取整，并对重叠帧预留比例。流式输出按片段顺序返回，意味着分块长度还影响首片段时延：分块越短首帧越早返回，但重叠比例上升、总前向次数增加，端到端时延未必下降。这是 SLO 与精度决策的交叉点。</p>\n<p>具体例子：在显存紧张时，把分块从长片段切为短片段并降低并发，可避免 OOM；但若同时把精度从 BF16 切到 FP8 以换回分块长度，必须重新校验重叠融合权重，因为量化误差在接缝处会被权重融合放大。论文材料未给出量化收益，因此容量规划只能按 BF16 做保守估计，把 FP8/NVFP4 视为需要监控的增量优化。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-19\">十九 · 工程判断：先固定累加精度，再逐层放开操作数精度</h3>\n<p>对这篇论文的部署路径，可执行的精度策略是：累加器固定 FP32，VAE 解码器与 FFN 先试 FP8 E4M3，时空注意力保持 BF16 直到接缝一致性监控通过，NVFP4 仅在权重侧小流量探索。判别器不参与推理，但其训练阶段的数值稳定性会影响学生权重分布，阶段间重置判别器时若学生权重已含低精度校准偏差，下一阶段的对抗均衡可能被打破，因此量化校准应放在阶段边界之后而非训练中途。</p>\n<p>监控项与失败模式一一对应：分块融合接缝闪烁对应注意力精度与重叠权重，显存峰值对应分块长度与批大小，片段时延对应 VAE 解码缓冲带宽。论文材料明确这些数字缺失，因此上线前的验证不是追求某个吞吐目标，而是确认在选定精度档下三类失败模式不出现。最终落在具体机制上：把 tcgen05/TMEM 的分块对齐、FP32 累加、按头分组 scaling 与重叠融合校验串成一条部署检查链，精度档位才可随显存档位与 SLO 逐级放开。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-20\">二十 · 单步前向的显存与数值边界：分块、融合与量化验证</h3>\n<p>单步学生把采样步数压到一，收益并不自动转化为吞吐：时间维被折叠进一次前向，时空注意力的激活张量按片段长度平方增长，VAE 解码缓冲又与像素分辨率线性相关，二者共同决定单次前向的显存峰值。设片段帧数 <i>F</i>、分辨率 <i>H×W</i>、批大小 <i>B</i>、注意力头数 <i>h</i>、每头维度 <i>d</i>，则单层时空注意力激活约为 <i>B·h·(F·H·W/16)²·d</i> 量级（潜空间按 8×8 下采样计），这一项随片段长度二次增长，是分块长度的硬约束；VAE 解码缓冲则约为 <i>B·F·H·W·3</i> 个半精度元素。工程上应先用该式反推片段上限，再让批调度在显存档位内填满剩余余量，而不是先定批大小再压缩片段。</p>\n<p>分块重叠融合是单步方案独有的失效点。重叠区域按权重融合时，若相邻片段在单步前向中得到的潜变量分布不一致（判别器均衡未收敛、或片段边界处教师参考轨迹缺失），接缝会以低频闪烁形式暴露。校验手段是按片段顺序做逐帧差分，把重叠权重与差分幅度联合监控；融合权重应随片段索引单调过渡，避免硬切换。表里给出三类代价的定性对照，便于在 B200/GB200 NVL72 档位上做取舍。</p>\n<table class=\"mini\"><thead><tr><th>代价项</th><th>随何增长</th><th>控制手段</th></tr></thead><tbody><tr><td>时空注意力激活</td><td>片段长度平方</td><td>缩短分块、降并发</td></tr><tr><td>VAE 解码缓冲</td><td>帧数×分辨率</td><td>解码与生成流水化</td></tr><tr><td>接缝闪烁</td><td>重叠比例与均衡偏差</td><td>权重过渡、差分监控</td></tr></tbody></table>\n<p>数值精度是第二个边界。单步学生没有多步迭代的误差平均效应，一次前向的舍入误差直接进入像素域；FP16 在注意力 softmax 与 VAE 解码的激活动态范围上易溢出，BF16 牺牲尾数换范围，FP8/NVFP4 则把尾数压到个位数，累加必须走 FP32 或更高位宽的分块累加，否则判别器均衡阶段的梯度噪声会被放大成模式崩溃的诱因。部署前应在 NVFP4/FP8 下对单步输出做逐片段退化检测：比较量化前后潜变量的相对误差与解码帧的接缝差分，任一项越界即回退到 BF16 档位。材料未给出该方案的量化稳定性数据，因此容量规划只能按分块与批大小做保守估计，把量化收益视为待验证项而非既定前提。</p>\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-21\">二十一 · 单步之后，显存账本的重心转移</h3>\n<p>把采样步数从数十步压到一步，账本上的第一反应是“KV cache 归零”。这个判断对视频扩散只对了一半：单步学生前向不再保留跨步的注意力键值，但时空注意力在一次前向内部仍要物化整段潜变量的 Q/K/V 与注意力输出，VAE 解码还要为像素片段开出大块缓冲。论文给出的代价描述很明确——单步采样把开销“转移到时空注意力激活与 VAE 解码缓冲”。因此本部分的显存账本必须按“权重 + 单次前向激活 + 解码缓冲 + 分块重叠冗余”四项来记，而不是按自回归 LLM 的“权重 + KV”两项来记。</p>\n<p>先给一个可复算的骨架。设潜变量形状为 <span>T×H×W</span>，通道数 <span>C</span>，注意力头数 <span>h</span>，头维 <span>d</span>，则单层时空注意力的激活字节数为：</p>\n<div class=\"formula\">$$M_{\\text{attn}} \\approx T H W C \\cdot b_{\\text{act}} \\cdot k_{\\text{mat}} + h\\,(T H W)\\, d \\cdot b_{\\text{act}} \\cdot 2$$</div>\n<p>其中 <span>b_act</span> 是激活位宽（BF16 为 2 字节，FP8 为 1 字节），<span>k_mat</span> 是单层内需要同时驻留的中间张量份数（Q、K、V、softmax 输出、残差等），第二项是 Q/K 的展开副本。工程上真正决定峰值的是 <span>k_mat</span> 与是否做 fused attention：把 Q/K/V 融合进一个 kernel、softmax 不落回 HBM，可以把 <span>k_mat</span> 从 5–6 压到 2–3，这是 Blackwell 上 tcgen05 与 TMEM 的直接收益点——中间结果留在张量内存而非 HBM，峰值显存与 HBM 往返同时下降。</p>\n<p>具体例子：一段 720p、49 帧的潜变量在 VAE 8× 空间压缩、4× 时间压缩后约为 <span>13×90×160</span>，通道 16，BF16 激活。单层 <span>THWC</span> 约 3.0×10⁷ 元素、60 MB；若 <span>k_mat</span>=5，单层驻留约 300 MB。一个 32 层的 DiT 若逐层串行、每层释放，激活峰值约 300 MB 量级；但若框架为反向或为融合保留多层的中间张量，峰值按层数线性放大，这就是“单步不等于省显存”的根因。权重侧按参数量 × 位宽计：BF16 下每 10 亿参数约 2 GB，FP8 减半，NVFP4 再减半——量化收益直接落在权重常驻上，而激活侧要靠 fused kernel 与分块，不靠位宽。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-22\">二十二 · 分块重叠：显存峰值的真正旋钮</h3>\n<p>论文的长视频路径是“按帧数与分辨率切分为带重叠的时空片段，每片段单步前向生成潜变量，重叠区域按权重融合”。这条路径把显存峰值从“整段视频”解耦为“单片段”，分块长度成为第一旋钮。设总帧数 <span>F</span>、分块帧数 <span>f</span>、重叠帧数 <span>o</span>，则片段数 <span>N = ⌈(F−o)/(f−o)⌉</span>，总计算冗余比为：</p>\n<div class=\"formula\">$$R_{\\text{overlap}} = \\frac{N f}{F} = \\frac{f}{f-o}\\left(1 + \\frac{o}{F}\\right)$$</div>\n<p>重叠是显存与质量的交换：<span>o</span> 越大，接缝越平滑，但片段数与总算力上升；<span>f</span> 越大，单次前向的 <span>THWC</span> 越大，激活峰值线性上升。工程判断是先把 <span>f</span> 压到显存档位允许的上限，再在接缝质量约束下取最小可接受 <span>o</span>。举例：<span>F</span>=49、<span>f</span>=17、<span>o</span>=4 时 <span>N</span>=4，冗余比约 1.39；若把 <span>o</span> 提到 8，<span>N</span>=5，冗余比升到 1.73，显存峰值不变但端到端时延增加约四分之一。这个账必须和 SLO 一起算，不能只看单片段时延。</p>\n<p>分块还带来一个容易被忽略的显存项：重叠融合缓冲。若框架保留全部片段的解码输出再统一加权融合，像素缓冲为 <span>N×f×H×W×3</span> 字节，1080p、<span>N</span>=5、<span>f</span>=17 时约 1.6 GB（uint8）到 3.2 GB（FP16），足以把一张卡的余量吃掉。正确做法是流式融合：只保留当前片段与前一 transpose 的重叠尾帧，按权重写入输出流，缓冲降到 <span>o×H×W×3</span> 量级。论文的“流式输出按片段顺序返回”正是这条路径，它同时把端到端显存从 O(N) 降到 O(1)。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-23\">二十三 · KV 与缓存复用：单步场景下还剩什么可缓存</h3>\n<p>单步学生没有跨步 KV，但“缓存”并未消失，只是换了对象。可复用的有三类：一是文本/条件编码的 cross-attention K/V，同一 prompt 在多片段间不变，可一次编码、全程复用，省掉每片段的文本塔前向与显存重分配；二是分块重叠区的潜变量，前一 transpose 的尾帧潜变量可直接作为当前片段的初始化条件，避免重复编码；三是 VAE 解码的中间特征，若解码器分块执行，块间边界特征可复用。这三类复用的共同点是“跨片段而非跨步”，与扩散多步缓存（如特征缓存、步间复用）是不同层次的机制，后者在单步下自然失效。</p>\n<p>代价上，条件 K/V 复用把每片段的文本塔前向从 <span>N</span> 次降到 1 次，文本塔若占单片段算力的一成，端到端可省近一成算力，且省下文本塔激活的重复峰值。但复用要求 K/V 常驻：以 77 token、1024 维、24 层、BF16 计，约 7.6 MB 量级，可忽略；真正要管的是复用生命周期与并发请求间的隔离——多请求共享同一文本塔实例时，K/V 缓冲需按请求分槽，槽位数就是并发上限的显存约束之一。分页在这里的意义不是 LLM 式的变长 KV 分页，而是把分块潜变量与解码缓冲按固定尺寸页管理，减少碎片与重分配抖动；论文未给出 KV 策略，工程上应按“条件 K/V 常驻 + 分块缓冲池化”落地。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-24\">二十四 · 带宽瓶颈：HBM3e 容量与单步的带宽账</h3>\n<p>单步把算力从数十次前向压到一次，算力不再是最紧的约束，带宽相对上升。一次前向的 HBM 流量近似为：权重读取 <span>P·b_w</span>（每 token 摊薄后接近一次全量读）+ 激活读写 <span>M_act·k_traffic</span>，其中 <span>k_traffic</span> 是激活在 HBM 与片上往返的次数。fused attention 把 <span>k_traffic</span> 从多次降到 1–2 次，这是 Blackwell 上 TMEM 与 2-SM MMA 的核心价值：中间矩阵不落 HBM。容量侧按 HBM3e 单堆栈 24 GB、8 堆栈 192 GB（B200 档）估算，权重、条件 K/V、分块激活池、解码缓冲、框架与通信缓冲要在这 192 GB 内分账。以 10B 参数、FP8 权重计约 10 GB，NVFP4 约 5 GB；激活池按最大分块的 2–3 倍留余量；解码缓冲按流式融合的 <span>o×H×W×3</span> 留；剩余给并发批与通信。GB200 NVL72 的每 GPU 容量同档，但跨 GPU 的 NVLink 5 带宽让“权重分片 + 激活本地”成为可行拓扑：权重按张量并行切分，激活与分块缓冲留在本地，避免激活跨链路往返。</p>\n<p>一个可复算的预算例子（10B 参数、FP8、720p/49 帧、<span>f</span>=17、<span>o</span>=4、并发 4）：权重 10 GB；条件 K/V 与文本塔 <1 GB；单请求激活池按单层 150 MB × 驻留 2 层 + 分块缓冲 ≈ 1 GB，四并发 4 GB；流式解码缓冲 <0.5 GB；框架与通信缓冲 4 GB；合计约 20 GB，远低于 192 GB。这说明容量不是瓶颈，峰值带宽与 kernel 效率才是——单步的端到端时延由一次前向的 HBM 流量除以有效带宽决定，权重读取占主导，故权重位宽（NVFP4/FP8）对时延的边际收益大于对容量的收益。反过来，若把并发拉到数十，激活池与解码缓冲线性增长，容量才重新成为约束；批调度“按片段长度与显存档位调整批大小”正是把并发压在容量拐点之下。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-25\">二十五 · 卸载与失败模式：账本要留余量</h3>\n<p>卸载在单步视频扩散里的对象不是 KV，而是权重与解码器。可行策略是分层卸载：把不参与当前分块的层权重留在 host 或 NVLink 对端，按层预取；VAE 解码器若与 DiT 不同时驻留，可在潜变量生成完后换入。代价是 PCIe/NVLink 传输与流水气泡，工程上只在容量紧张时启用，且预取深度要覆盖一次前向的层间间隔。论文未给出并行拓扑与 KV 策略，卸载只能作为兜底而非默认。</p>\n<p>失败模式要写进账本：把单步收益直接等同于吞吐提升，忽略 VAE 解码与时空注意力激活的显存峰值，会在长视频高分辨率下 OOM；分块重叠融合不当会在接缝处产生闪烁，需按重叠权重与片段顺序校验，且融合缓冲若未流式化会反噬显存；未验证 NVFP4/FP8 数值稳定性即上线，单步学生输出可能退化，量化收益无法核验。监控项应落在分块融合接缝、显存峰值与片段时延三处，失败时降批或缩短分块——这是论文给出的调度回退路径，也是容量规划必须预留的余量：按峰值显存的八成设定批上限，把两成留给碎片、融合缓冲与突发并发。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-26\">二十六 · 单步采样之后的真实账本：显存峰值、带宽瓶颈与分块边界</h3>\n\n<p>把采样步数从数十步压到一步，省掉的是迭代链上的激活累积与反复读写，但并没有让显存需求归零——它只是把账本的重心从“步数×每步激活”搬到了“单次前向的时空注意力激活 + VAE 解码缓冲”。设片段帧数 <em>F</em>、分辨率 <em>H×W</em>、潜通道 <em>C</em>、批大小 <em>B</em>，潜张量规模约为 <em>B·C·F·(H/8)·(W/8)</em>（VAE 下采样倍率按实现而定）；时空注意力在序列维上展开后，注意力分数矩阵随 token 数平方增长，这是单步前向里最不可压缩的一项。工程上可复算的粗账是：<div class=\"formula\">$$M_{\\text{peak}} \\approx \\underbrace{B\\cdot C\\cdot F\\cdot \\tfrac{H}{8}\\cdot \\tfrac{W}{8}\\cdot s}_{\\text{潜张量与中间激活}} + \\underbrace{\\alpha\\,B\\cdot N_{\\text{tok}}^2\\cdot h}_{\\text{时空注意力分数}} + \\underbrace{M_{\\text{VAE}}}_{\\text{解码缓冲}} + M_{\\text{weights}}$$</div>其中 <em>s</em> 为每元素字节数（FP8 取 1、BF16 取 2），<em>N<sub>tok</sub></em> 为片段内时空 token 数，<em>h</em> 为注意力头数维度因子，<em>α</em> 取决于是否使用分块注意力和是否复用 KV。这个式子的用途不是精确预测，而是判断“缩谁最有效”：当 <em>N<sub>tok</sub></em> 项占主导时，降批大小几乎无用，必须缩短分块帧数或引入注意力分块；当 <em>M<sub>VAE</sub></em> 项占主导时，缩短分块反而增加解码调用次数与重叠冗余。</p>\n\n<p>带宽侧的瓶颈位置与显存不同。单步前向把权重读取摊到一次，权重带宽压力相对可控；真正吃带宽的是潜张量在注意力、归一化、VAE 解码之间的往返搬运，以及分块重叠区域在融合时的重复读写。重叠比例 <em>r</em>（重叠帧数/片段帧数）直接放大有效计算量：总前向次数约为 <em>⌈(T−F)/(F(1−r))⌉+1</em>，<em>T</em> 为总帧数。重叠越大，接缝越稳，但带宽与算力按 <em>1/(1−r)</em> 放大。在 GB200 NVL72 这类档位上，HBM3e 容量决定了能同时驻留多少片段的激活与解码缓冲，而 NVLink 5 的域内带宽决定了分块结果跨 GPU 汇聚融合的成本——若把融合放在主机侧，PCIe 往返会成为新的隐性瓶颈，应尽量在 GPU 侧按重叠权重做加权累加。容量规划的保守做法是：先按最坏片段（最长帧数、最高分辨率、最大批）算出 <em>M<sub>peak</sub></em>，再留出 VAE 解码与融合缓冲的余量，剩余容量才分配给并发片段数；论文未给出吞吐与显存实测数字，因此并发数只能按此上界反推，不能按“单步=快数倍”直接外推。</p>\n\n<p>失效条件集中在三处。其一，把单步收益等同于吞吐提升：采样步数下降后，单次前向的时空注意力激活峰值可能反而高于多步中的单步峰值（因为多步可用更小分块逐步推进），若批调度仍按旧档位配置，会直接触发显存溢出而非加速。其二，分块重叠融合不当：重叠权重若按固定线性权重而非按片段顺序与运动连续性校验，接缝处会出现闪烁，这类失败在监控上表现为片段时延正常但端到端视频质量下降，属于“账本平衡但语义失真”。其三，未验证 NVFP4/FP8 数值稳定性即上线：单步学生没有多步迭代的误差平均效应，量化误差在单次前向中被完整放大，输出退化不会像多步采样那样被后续步骤部分修正。工程判断是：分阶段对抗均衡解决的是分布偏离，不解决数值鲁棒性；量化验证必须独立于蒸馏阶段进行，并把分块融合接缝、显存峰值、片段时延三项作为上线前的硬门禁，显存不足时优先缩短分块而非降精度。</p>\n\n<table class=\"mini\"><thead><tr><th>账本项</th><th>随什么增长</th><th>主要缓解手段</th><th>失效信号</th></tr></thead><tbody><tr><td>时空注意力分数</td><td>片段 token 数平方</td><td>缩短分块、注意力分块</td><td>显存峰值随帧数陡增</td></tr><tr><td>VAE 解码缓冲</td><td>像素片段尺寸×批</td><td>降批、流式解码</td><td>解码阶段 OOM</td></tr><tr><td>重叠冗余</td><td>1/(1−r)</td><td>调重叠比例与融合权重</td><td>接缝闪烁、带宽饱和</td></tr><tr><td>量化误差</td><td>单步前向无平均</td><td>NVFP4/FP8 独立验证</td><td>输出退化、细节丢失</td></tr></tbody></table>\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-27\">二十七 · 单步前向把调度问题从“步数”搬到“片段”</h3>\n<p>在教师多步采样里，调度器面对的是一个天然均匀的时间轴：每个请求要跑几十步，每步的计算量近似相同，批处理只要把同一时刻的请求拼在一起就能填满 SM。分阶段单步对抗均衡把这个时间轴压成了一步，调度对象随之改变——请求不再由“步”组成，而由“带重叠的时空片段”组成。长视频先按帧数与分辨率切分，每个片段以单步学生前向生成潜变量，再经 VAE 解码为像素片段，重叠区域按权重融合。于是连续批处理的粒度从“步”变成“片段”，而片段长度直接决定单次前向的显存峰值：时空注意力激活与 VAE 解码缓冲是两块主要占用，前者随片段内 token 数增长，后者随像素分辨率增长。</p>\n<p>这带来一个与 LLM 连续批处理不同的约束。LLM 的 KV cache 随序列增长而单调累积，调度器可以用分页管理把它切成块；单步视频扩散没有跨步累积的 KV，但每个片段是一次性的大激活，峰值出现在单次前向内部。设片段含 \\(F\\) 帧、分辨率 \\(H\\times W\\)、潜空间下采样率为 \\(s\\)，则单片段潜变量 token 数近似为</p>\n<div class=\"formula\">$$N_{\\text{tok}} \\approx \\frac{F\\cdot H\\cdot W}{s^{2}}$$</div>\n<p>注意力激活与 \\(N_{\\text{tok}}\\) 的关系是超线性的（时空注意力在时间维与空间维上都要做全局交互），而 VAE 解码缓冲与 \\(F\\cdot H\\cdot W\\) 成正比。调度器要做的第一个判断不是“这批能塞几个请求”，而是“这个片段长度在目标档位的显存里能不能放下一个最小可用批”。在 B200/GB200 NVL72 上，这意味着分块长度是一个必须先于批大小确定的量：显存不足时先缩短分块，再降并发，顺序不能反，否则会把尾延迟推高。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-28\">二十八 · 连续批处理在片段粒度上的重组</h3>\n<p>把连续批处理搬到片段粒度，核心是把“请求级”与“片段级”两级队列分开。请求进入后先做切分规划：按帧数与分辨率生成片段序列，每个片段带一个重叠长度与融合权重。调度器维护两个队列——待切分请求队列与就绪片段队列——并按片段长度分桶。分桶的理由是单步前向的耗时对 \\(N_{\\text{tok}}\\) 敏感，长短片段混批会让短片段等长片段，尾延迟被长片段拖住。工程上常见的做法是给每个桶设一个目标批大小 \\(b_k\\)，桶内按先到先服务，桶间按权重轮转，权重由该桶的 SLO 紧迫度决定。</p>\n<p>一个可落地的伪代码思路是：</p>\n<ul>\n<li>对每个新请求，按显存档位查表得到最大片段长度 \\(L_{\\max}\\)，切分为 \\(\\lceil T/L_{\\max}\\rceil\\) 个片段，相邻片段重叠 \\(o\\) 帧；</li>\n<li>片段入桶时记录其 token 数 \\(N_{\\text{tok}}\\) 与解码像素量，作为该片段的“代价标签”；</li>\n<li>调度循环每次从桶中取片段，累计代价标签直到触及显存预算 \\(M_{\\text{budget}}\\) 或批大小上限，形成一次前向的批；</li>\n<li>前向完成后片段进入 VAE 解码队列，解码可与下一批前向重叠，形成两级流水。</li>\n</ul>\n<p>代价在于：分桶会降低批的填充率，桶越多、填充率越低，吞吐下降；桶越少、长短混批越严重，尾延迟上升。这个取舍在单步视频扩散上比 LLM 更尖锐，因为单片段前向的耗时差异可以达到数倍，而 LLM 的单步 decode 耗时差异通常只有常数级。工程判断是：按分辨率而非按帧数分桶，因为分辨率对 VAE 解码缓冲的影响更刚性，帧数可以通过重叠切分柔性调整。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-29\">二十九 · Chunked prefill 的对应物：分块前向与解码流水</h3>\n<p>LLM 的 chunked prefill 把长 prompt 切成小块与 decode 混批，目的是压住 prefill 造成的尾延迟尖峰。视频扩散里没有严格对应的 prefill/decode 二分，但有一个结构相似的对应物：把长视频的片段前向（计算密集、显存峰值高）与已生成片段的 VAE 解码（带宽密集、显存峰值低）做成两条流水，让解码填充分块前向留下的显存与带宽空隙。单步学生的前向是计算密集的，时空注意力吃满 tensor core；VAE 解码是带宽密集的，吃 HBM 带宽与解码缓冲。两者混跑可以在同一时间窗内同时利用算力与带宽，这是 Blackwell 档位上少有的“免费”重叠机会。</p>\n<p>代价是显存预算要同时容纳前向激活与解码缓冲，混跑的批大小必须按两者之和来定，而不是各自独立定。设前向批的激活峰值为 \\(A_{\\text{fwd}}\\)、解码缓冲为 \\(A_{\\text{dec}}\\)，则约束是</p>\n<div class=\"formula\">$$A_{\\text{fwd}}(b_{\\text{fwd}}, L) + A_{\\text{dec}}(b_{\\text{dec}}, F, H, W) \\le M_{\\text{avail}}$$</div>\n<p>工程上把 \\(b_{\\text{dec}}\\) 设为固定的小值（解码本身并行度高、单批就能吃满带宽），把剩余预算全给 \\(b_{\\text{fwd}}\\)，这样流水不会因为解码抢占而让前向批缩水。一个具体例子：生成一段长视频时，调度器先把前两个片段的前向排进同一批，解码队列空转；从第三个片段起，前一批的解码与前向重叠，显存预算按上式分配，前向批大小稳定在桶的目标值，尾延迟由最长片段的前向时间决定而不是由解码排队决定。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-30\">三十 · 优先级、抢占与尾延迟的压制</h3>\n<p>视频生成的 SLO 通常是端到端时延加片段时延双约束，且流式输出要求片段按顺序返回。这给优先级设计带来一个硬约束：片段之间有顺序依赖，不能像 LLM 请求那样任意抢占重排。可行的做法是把优先级放在请求级而非片段级：高优先级请求的片段整体插队，但同一请求内的片段严格按序执行。抢占的粒度是“批内片段替换”——当高优先级片段到达而当前批已满，调度器可以驱逐批内最低优先级的片段，被驱逐片段回到桶头，其已分配但未使用的显存预算释放。</p>\n<p>尾延迟的来源有三个，需要分别压：其一是长片段本身的前向时间，靠分块长度上限压；其二是桶内排队，靠桶间权重轮转与预留槽位压；其三是重叠融合的串行等待，靠把融合做成增量式——每生成一个片段就与前一片段的重叠区做加权融合，而不是等全部片段生成完再统一融合。融合权重按重叠区内位置线性或余弦衰减，接缝处的闪烁由权重曲线与片段顺序共同决定，调度器只需保证融合在前向之后立即执行，不引入额外排队。</p>\n<p>代价是抢占会浪费已投入的前向计算。单步前向没有中间状态可保存，被驱逐片段的工作全部作废，这与 LLM 抢占可以保留 KV cache 不同。因此抢占阈值要设得保守：只有当高优先级片段的 SLO 余量低于其单片段前向时间的若干倍时才触发，否则宁可让高优先级请求在桶间轮转中优先取批。尾延迟的压法归根到底是把“最长片段的前向时间”作为调度周期的上界，所有其他延迟都必须小于这个上界，否则就会叠加。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-31\">三十一 · 分离式预填/解码在单步视频上的映射</h3>\n<p>分离式预填/解码把计算密集的 prefill 与带宽密集的 decode 放到不同资源池，按各自的最优批大小独立扩缩容。单步视频扩散的映射不是照搬，而是把“片段前向”与“VAE 解码”分离到不同 GPU 组：前向组配大显存、吃满 tensor core，解码组配高带宽、吃满 HBM。分离的收益来自两边的最优批大小不同——前向组希望批尽量大以摊薄权重读取，解码组希望批小、并发高以填满带宽。合在一起时，批大小被迫取两者约束的交集，两边都不在最优工作点。</p>\n<p>代价是片段潜变量要在两组之间传输，走 NVLink 5 或 NIXL 这类传输路径。潜变量的体积远小于像素视频，传输量按 \\(N_{\\text{tok}}\\times\\) 通道数估算，相对于像素解码缓冲可以忽略；但传输延迟会进入端到端时延，需要在流水设计里用双缓冲掩盖。工程判断是：当解码组的带宽利用率长期低于前向组的算力利用率时，分离才划算；若两者利用率接近，合并部署的通信开销更低。GB200 NVL72 的机架内 NVLink 域让这种分离的传输代价可控，但跨机架分离就要重新算这笔账。</p>\n<p>分离后尾延迟的压法也变了：端到端时延变成前向时间、传输时间、解码时间三者之和的最大路径，调度器要保证三者中没有一个成为周期性瓶颈。具体做法是给解码组设一个略大于前向组产出速率的服务能力，让解码队列长度稳定在一个小值，既不空转也不堆积。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-32\">三十二 · 容量规划：按分块与批大小做保守估计</h3>\n<p>论文未给出数据集、FVD、吞吐与端到端时延数字，容量规划只能按分块与批大小做保守估计，不能把单步蒸馏的步数收益直接等同于吞吐提升。正确的估算顺序是：先定目标档位的可用显存，减去 VAE 解码缓冲与运行时开销，得到前向激活预算；再用时空注意力的激活模型反推单片段最大 token 数，得到分块长度上限；最后按桶的目标填充率估算稳态吞吐。吞吐的上界由前向组的算力决定，但实际值要被解码流水与融合串行打折。</p>\n<p>监控要盯三个量：分块融合接缝的视觉一致性、显存峰值、片段时延分布的分位数而非均值。失败模式里最隐蔽的一条是未验证 NVFP4/FP8 数值稳定性就上线——单步学生没有多步迭代的误差摊薄，量化误差会直接体现在输出上，表现为细节退化而非崩溃，监控若不看接缝与纹理指标就发现不了。调度侧的应对是把量化验证作为上线前的门禁，并在运行时对片段输出做轻量一致性校验，异常时降批或缩短分块，用保守配置换稳定性。容量规划因此要留出一档“降级运行”的显存余量，而不是把预算压到极限。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-33\">三十三 · 单步采样下的调度边界：分块、批与尾延迟</h3>\n<p>单步前向把采样步数压到一步，调度器的优化目标随之改变：不再是“步间流水线填充”，而是“单次前向的显存峰值与片段时延”。长视频按帧数与分辨率切分为带重叠的时空片段，分块长度直接决定单次前向的激活峰值，而 VAE 解码缓冲与时空注意力激活共同构成显存主项。设片段数为 $N$、单片段前向时延 $t_f$、解码时延 $t_d$、融合开销 $t_m$，端到端时延近似为 $T \\approx \\sum_{i=1}^{N}(t_f^{(i)}+t_d^{(i)})+t_m$，吞吐则受批大小 $B$ 与显存档位约束：$B_{\\max}\\approx \\lfloor M_{\\text{free}}/m_{\\text{seg}}\\rfloor$，其中 $m_{\\text{seg}}$ 为单片段峰值显存。连续批处理在这里退化为“按片段长度与显存档位动态调批”，显存不足时缩短分块或降并发，而不是靠抢占腾挪——因为单步前向没有可中断的迭代步，抢占只能丢弃整片段重算。</p>\n<p>这带来两个失效条件。其一，尾延迟不再由最长请求决定，而由最长片段链决定：流式输出按片段顺序返回，若某片段因显存压缩被迫缩短分块，重叠区增多、融合开销上升，端到端时延反而拉长。其二，chunked prefill 式的细粒度切分在单步学生上收益有限，因为每片段只做一次前向，切分带来的调度开销与重叠冗余会吃掉并行收益。工程判断是：把分块长度作为一等调度参数，按显存档位设上限，优先保证片段内一次前向完成，而非追求更高并发。</p>\n<table class=\"mini\"><thead><tr><th>调度动作</th><th>触发条件</th><th>代价</th></tr></thead><tbody><tr><td>降批大小</td><td>显存峰值逼近档位上限</td><td>吞吐下降，片段时延基本不变</td></tr><tr><td>缩短分块</td><td>单片段激活超限</td><td>重叠区增多，融合开销与接缝风险上升</td></tr><tr><td>顺序流式返回</td><td>长视频多片段</td><td>首片段时延低，端到端受最长链约束</td></tr></tbody></table>\n<p>分离式预填/解码在此方案中并不对称：教师多步采样只在训练侧出现，推理侧没有可分离的预填阶段，因此“预填/解码分离”退化为“分块前向/VAE 解码分离”——把解码缓冲独立成池，避免与注意力激活争抢同一显存档位。代价是解码池与激活池之间的数据搬运增加带宽压力，在 B200/GB200 NVL72 上需按带宽配置决定是否值得。尾延迟的压制手段因此收敛为三条：固定分块上限使单片段时延可预测、按重叠权重预校验接缝、以及在 NVFP4/FP8 未验证前保留高精度回退路径，避免数值退化导致的片段重算把尾延迟推高。</p>\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-34\">三十四 · 并行拓扑与单步学生的映射关系</h3>\n<p>把分阶段单步对抗蒸馏的学生网络放到 Blackwell 集群上，第一件事不是选框架，而是确定切分维度与单步前向的匹配关系。单步学生的一次前向要同时承担潜变量生成与时空注意力建模，其计算图与多步教师并无本质差异，但采样步数塌缩为一步后，单次前向的权重加载与激活峰值被放大——原本分摊在数十步里的显存压力集中到一次调用中。TP（张量并行）切分注意力头与 MLP 中间维，适合单卡放不下完整权重时的带宽换显存；EP（专家并行）只在学生含 MoE 结构时才有意义，视频扩散主干通常为稠密 Transformer，EP 更多出现在多模态编码侧；PP（流水并行）把时空 Transformer 层按深度切段，代价是段间激活的搬运与流水气泡，对单步这种“一次前向即结束”的负载，气泡占比远高于多步迭代，因为多步时气泡可被后续步掩盖，单步没有后续步；DP（数据并行）复制权重、切分片段批次，是长视频分块重叠方案最自然的并行方式，因为每个时空片段彼此独立，重叠融合在主机侧完成。</p>\n<p>工程判断落在一条不等式上：设单片段单步前向的计算量为 <span>C</span>、权重驻留显存为 <span>W</span>、激活峰值为 <span>A</span>，则 TP 度 <span>t</span> 与 PP 度 <span>p</span> 的组合必须满足 <span>W/(t·p) + A/t ≤ M<sub>cap</sub></span>，其中 <span>M<sub>cap</sub></span> 是单卡可用显存（扣除 VAE 解码缓冲与框架开销）。这条式子说明：PP 对权重有效、对激活无效，而单步学生的激活峰值恰恰来自时空注意力，所以 PP 只能解决“权重放不下”，解决不了“激活爆掉”。真正压激活的是分块长度与 TP 对注意力的切分。举例：一个 720p、数十帧的片段在单卡上激活峰值超出容量时，先缩分块长度比加 PP 更直接，因为缩短分块同时降低注意力的序列长度平方项。</p>\n<div class=\"formula\">$$\\text{单步前向时间} \\approx \\frac{C}{t\\cdot p \\cdot \\eta_{\\text{MMA}}} + \\frac{W}{t\\cdot p \\cdot B_{\\text{HBM}}} + \\tau_{\\text{comm}}(t,p)$$</div>\n<p>式中第三项是通信代价，<span>η<sub>MMA</sub></span> 为 tcgen05 类 MMA 的利用率，<span>B<sub>HBM</sub></span> 为显存带宽。单步负载下前两项被压缩到极短，第三项的相对占比随之上升——这是本部分的核心论点：步数蒸馏把计算砍掉一个数量级，通信没有跟着砍，于是通信从“可掩盖”变成“主导”。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-35\">三十五 · NVLink 5 与 NVSwitch：集合通信的物理底座</h3>\n<p>GB200/GB300 NVL72 机柜内以 NVLink 5 互联，配合 NVSwitch 构成全连接域，域内 All-Reduce、All-to-All、All-Gather 不必绕行 InfiniBand。对单步学生而言，TP 的每次前向要在每层注意力与 MLP 后做 All-Reduce（或 Reduce-Scatter + All-Gather 的等价分解），PP 要在段边界做点对点激活搬运，DP 在梯度侧才需要 All-Reduce，推理时 DP 几乎无集合通信——这一点常被误判：推理 DP 的通信量近似为零，瓶颈在主机侧的分块调度与结果融合，而非链路。EP 的 All-to-All 在稠密视频主干中不出现，但若学生接入多模态编码器或稀疏专家层，All-to-All 的突发性会与单步前向的短时窗冲突，因为 All-to-All 是延迟敏感型操作，缺乏计算可掩盖。</p>\n<p>把 TP 的通信量写成显式代价：每层 All-Reduce 搬运 <span>2·(t−1)/t·S</span> 字节，<span>S</span> 为该层输出激活字节数；单步前向共 <span>L</span> 层，则单次前向的 TP 通信总量为 <span>2L·(t−1)/t·S</span>。当 <span>t</span> 从 2 增到 8，通信量按 <span>(t−1)/t</span> 趋近饱和但每层延迟随跳数增加，NVSwitch 域内的跳数虽为常数级，集合操作的同步开销仍随 rank 数上升。具体例子：在 NVL72 内做 8 路 TP，单步前向的每层 All-Reduce 若不能在下一层 MMA 启动前完成，就会暴露为串行延迟；由于单步没有后续采样步来掩盖，这些延迟直接进入端到端片段时延。工程上的做法是把 TP 度控制在能覆盖权重与激活的最小值，把剩余并行度让给 DP 的分块并发。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-36\">三十六 · NIXL 传输与分离式部署的接缝</h3>\n<p>NIXL 面向的是节点间与存储间的点对点数据传输，在分离式预填/解码或跨节点分块流水里承担潜变量、VAE 输入输出与中间激活的搬运。对本文的单步学生，NIXL 最相关的场景是长视频分块后的片段级流水：片段 A 在节点 1 生成潜变量，片段 B 在节点 2 生成，重叠区域需要在融合前把边界潜变量传到同一侧。若把融合放在主机侧，NIXL 搬运的是压缩后的潜变量而非像素，字节数远小于 VAE 解码后的视频帧，这是分块方案能扩展的前提。反之，若先把每块解码成像素再跨节点拼接，NIXL 的带宽需求会随分辨率与帧数线性膨胀，直接把单步省下的计算收益吃掉。</p>\n<p>代价判断可以写成一条带宽账：设片段潜变量字节数为 <span>Z</span>、重叠区比例为 <span>r</span>、并发片段数为 <span>n</span>，则融合阶段的跨节点搬运量约为 <span>2·r·Z·n</span>（双向边界）。当 <span>n</span> 增大以填满 GPU 时，这笔搬运与 VAE 解码缓冲的显存占用同步上升，形成“并发换吞吐、搬运换显存”的取舍。具体机制上，NIXL 的传输应与片段调度解耦：调度器先按显存档位定分块长度与并发数，再把跨节点边界传输排进片段生成的空隙，避免传输与时空注意力 MMA 争抢同一时窗。若传输落在关键路径上，单步前向的短时延会被传输抖动放大，表现为片段时延的方差异常。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-37\">三十七 · 通信何时成为瓶颈：三个判据</h3>\n<p>判据一，计算通信比。单步前向把每层的计算时间压到 <span>C<sub>layer</sub>/(t·η)</span>，而 All-Reduce 延迟 <span>τ</span> 不随步数下降，当 <span>τ > C<sub>layer</sub>/(t·η)</span> 时该层无法被计算掩盖，通信进入关键路径。多步采样时这个比值被后续步稀释，单步时没有稀释空间。判据二，分块长度与序列长度的平方关系。时空注意力的计算随序列长度平方增长，而 TP 的通信随激活字节线性增长，缩短分块会让计算先降、通信占比后升，存在一个使通信占比陡增的拐点；容量规划应停在该拐点之上，宁可少并发也不要把分块切得过碎。判据三，VAE 解码与传输的重叠度。VAE 解码是显存与带宽密集型且难以与注意力 MMA 重叠，若解码缓冲与 NIXL 传输同时占用显存带宽，单步前向的有效带宽被挤压，表现为片段时延的非线性上升。</p>\n<table class=\"mini\"><thead><tr><th>并行维度</th><th>切分对象</th><th>单步负载下的主要代价</th><th>何时成为瓶颈</th></tr></thead><tbody><tr><td>TP</td><td>注意力头、MLP 中间维</td><td>每层 All-Reduce 延迟，无后续步掩盖</td><td>层计算时间低于集合通信延迟</td></tr><tr><td>PP</td><td>Transformer 层深度</td><td>段间激活搬运与流水气泡</td><td>单次前向气泡占比高，段数大于可掩盖深度</td></tr><tr><td>DP</td><td>时空片段批次</td><td>主机侧融合与显存复制</td><td>片段数超过显存档位允许的并发</td></tr><tr><td>EP</td><td>专家/多模态分支</td><td>All-to-All 突发延迟</td><td>稀疏层与单步短时窗冲突</td></tr></tbody></table>\n<p>具体例子：一个高分辨率长视频请求被切成带重叠的片段，若为压显存把分块缩到很短，TP 的每层 All-Reduce 在总时延中的占比会明显上升，此时增加 DP 并发反而比继续缩分块更划算，因为 DP 推理几乎不引入集合通信，代价转移到主机侧融合与显存复制。反过来，若权重本身放不下单卡，TP 是唯一选择，此时应把 TP 度压到刚好容纳权重与激活，并用分块长度而非 TP 度去调激活峰值。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-38\">三十八 · 与分阶段均衡机制的耦合点</h3>\n<p>分阶段对抗蒸馏在推理侧留下的痕迹是学生权重的共享与判别器的重置，并行拓扑必须与这一结构对齐。阶段间共享学生权重意味着 TP/PP 的切分方案在阶段切换时不应改变，否则权重重排会引入额外的搬运与重新分片开销；判别器只在训练侧存在，推理拓扑不必为其预留 EP 或 PP 段。单步学生在强对抗下的模式崩溃风险，在系统侧表现为输出分布的退化，而并行切分本身不改变数值语义——除非量化介入。材料未给出 NVFP4/FP8 下的数值稳定性数据，因此并行方案应保留一条可回退的高精度路径：当监控发现分块接缝闪烁或片段间分布漂移时，先降 TP 度以减少跨卡归约的数值路径长度，再考虑回退精度，而不是直接加并发。</p>\n<p>监控指标应落在三个量上：片段时延的方差（通信抖动的代理）、显存峰值与 VAE 解码缓冲的占比（分块长度是否过碎）、跨节点搬运量与片段生成时间的比值（NIXL 是否进入关键路径）。这三个量共同决定并行拓扑是否该调整，而不是靠单一吞吐数字判断。单步采样把采样步数从数十步降到一步，收益是确定的，但收益能否兑现为端到端吞吐，取决于通信是否被压在计算之下——这正是本部分要落的工程判断：先定分块与并发，再定 TP 度，最后才谈链路利用率。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-39\">三十九 · 单步前向下的通信边界：并行拓扑何时失效</h3>\n<p>该方案推理侧只有一次学生前向，通信结构因此与多步教师采样截然不同：多步采样中每步都要同步注意力分片与 KV 交换，通信量随步数累积；单步前向把同步次数压到一次，但单次前向的时空注意力激活规模反而更大，分块长度直接决定单卡显存峰值。此时 TP 的 All-Reduce 规模取决于隐藏维切分，EP 的 All-to-All 取决于专家路由，PP 的微批气泡在单步前向下几乎无摊销空间——流水线只有在连续片段流式请求时才划算。判断通信是否成为瓶颈，可用单片段通信占比刻画：</p>\n<div class=\"formula\">$$\\eta_{\\text{comm}}=\\frac{T_{\\text{comm}}}{T_{\\text{comm}}+T_{\\text{attn}}+T_{\\text{vae}}}$$</div>\n<p>当 η_comm 随分块长度增大而上升，说明时空注意力激活已把单卡显存推高，被迫跨卡切分注意力头，NVLink 5 与 NVSwitch 的域内带宽被激活搬运占满；此时缩短分块比加卡更有效，因为加卡会引入新的 All-Reduce 与重叠融合同步。表里给出三种拓扑在该方案下的典型代价位置。</p>\n<table class=\"mini\"><thead><tr><th>拓扑</th><th>主要通信</th><th>代价落点</th></tr></thead><tbody><tr><td>TP</td><td>每层 All-Reduce</td><td>注意力头切分后激活同步，随分块长度上升</td></tr><tr><td>EP</td><td>All-to-All</td><td>路由不均衡时单卡等待，单步前向无步数摊销</td></tr><tr><td>PP</td><td>激活传递</td><td>微批气泡，片段流不连续时利用率下降</td></tr></tbody></table>\n<p>NIXL 传输在分离式预填/解码场景才有意义：该方案学生单步生成与 VAE 解码耦合在同一进程，若把 VAE 解码拆到独立节点，潜变量需经 NIXL 搬运，重叠融合的接缝校验也要跨节点同步，端到端时延反而被传输主导。失效条件很具体：分块重叠比例过高导致融合同步次数上升；批调度在显存不足时缩短分块，使每片段通信占比升高；未验证 NVFP4/FP8 数值稳定性就上线，单步学生输出退化后重试放大通信。工程判断是先把分块长度与批大小压在单卡显存水位内，让 TP 域收敛到 NVLink 5 域内，再考虑跨节点并行。</p>\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-40\">四十 · 精度塌陷：单步学生的分布漂移如何被观测</h3>\n<p>单步学生把教师数十步的采样轨迹压成一次前向，误差不再有逐步修正的机会，任何数值偏差都会直接落到像素上。分阶段对抗均衡的机制本身决定了失败形态：每个阶段固定判别器强度训练学生若干步，阶段间共享学生权重并重置判别器，一旦某一阶段判别器相对学生过强，学生会被推向判别器易判真的少数模式，表现为运动幅度收缩、纹理重复、长视频后段趋于静止。这类塌陷不是 loss 曲线上的尖峰，而是分布层面的缓慢偏移，因此监控必须落在输出统计量上，而不是只看蒸馏损失与对抗损失的加权和。</p>\n<p>可落地的观测量是片段级的一阶与二阶统计：相邻帧差的均值（运动能量）、潜变量通道方差的时序漂移、以及重叠区融合前后的像素差。把教师多步采样在相同初始噪声下生成的参考片段作为基线，按片段计算学生输出与参考的潜变量距离，形成每段的漂移分数。判定阈值不设全局常数，而按分块长度与分辨率分档，因为分块越短，单次前向的时空注意力感受野越受限，统计量本身波动更大。</p>\n<div class=\"formula\">$$d_t=\\frac{\\lVert \\hat{z}_t-\\tilde{z}_t\\rVert_2}{\\lVert \\tilde{z}_t\\rVert_2+\\epsilon},\\qquad \\text{alert if } \\operatorname{median}_{t\\in W}(d_t)&gt;\\tau(\\text{tile},\\text{res})$$</div>\n<p>代价在显存与带宽：保留教师参考轨迹意味着额外的潜变量缓冲，长视频按带重叠的时空片段切分后，参考缓冲随片段数线性增长，与时空注意力激活、VAE 解码缓冲争抢同一档显存。工程上的折中是只在抽样片段上跑教师参考，按固定间隔抽样而非全量比对，把诊断开销压到推理主路径之外。具体例子：一段长视频切成若干带重叠片段，若某片段的漂移分数中位数连续越过阈值，先判定为该片段分辨率档位下的精度塌陷，而不是直接回滚全局权重。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-41\">四十一 · OOM 与显存峰值：分块长度是唯一硬旋钮</h3>\n<p>单步采样把采样步数从数十步降到一步，省掉的是迭代累积，但显存峰值并没有同步下降——主要代价转移到时空注意力激活与 VAE 解码缓冲。分块长度直接决定单次前向的激活规模，因此 OOM 的第一定位动作不是降批大小，而是确认当前分块长度与分辨率组合是否越过了该档位的激活上限。批调度按片段长度与显存档位调整批大小，显存不足时降低并发或缩短分块，这两条路径的代价不同：降并发损失吞吐但保持分块语义，缩短分块则改变重叠融合的接缝结构。</p>\n<p>峰值估算可按激活与解码缓冲两块做保守上界：激活随分块帧数、分辨率与注意力头维度增长，解码缓冲随输出像素片段增长，二者在时间上部分重叠。监控应采集每次前向的显存高水位而非平均值，因为 OOM 由瞬时峰值触发。B200/GB200 NVL72 档位上，单卡显存与 NVLink 5 带宽决定了分块与并发的可行组合，跨卡切分片段会引入通信开销，需与单卡缩短分块做对比。</p>\n<table class=\"mini\"><thead><tr><th>现象</th><th>首要定位</th><th>处置</th><th>代价</th></tr></thead><tbody><tr><td>单次前向 OOM</td><td>分块帧数×分辨率</td><td>缩短分块</td><td>接缝增多，融合权重需重校验</td></tr><tr><td>并发上升后 OOM</td><td>批大小×片段长度</td><td>降并发</td><td>吞吐下降，尾延迟改善</td></tr><tr><td>VAE 解码阶段 OOM</td><td>像素片段缓冲</td><td>解码分片</td><td>解码吞吐下降，显存峰值削平</td></tr></tbody></table>\n<p>具体例子：同一请求在短分块下稳定运行，换成长分块后偶发 OOM，且高水位出现在 VAE 解码而非注意力阶段，说明瓶颈在像素缓冲而非激活，此时降批大小无效，应改为解码分片。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-42\">四十二 · 批抖动与尾延迟：流式输出的片段顺序约束</h3>\n<p>流式输出按片段顺序返回，这一约束把批调度从吞吐问题变成尾延迟问题。片段长度不均时，按显存档位动态调整批大小会让批组成频繁变化，形成批抖动：短片段快速进出，长片段拖住整个批的完成时间，端到端视频时延由最慢片段决定。SLO 以片段生成时延与端到端视频时延两个口径衡量，前者受批内排队影响，后者受片段顺序与重叠融合影响，两者不能互相替代。</p>\n<p>定位批抖动的方法是记录每个片段的入队时刻、开跑时刻与完成时刻，计算排队时延的方差；方差抬升而单片段计算时延稳定，说明批组成在抖动而非算力不足。处置上优先做片段长度分桶，把相近长度的片段放入同一批，减少批内长尾；其次对重叠区融合做流水化，让下一片段的前向与当前片段的融合重叠执行。代价是分桶降低批的填充率，短片段桶的算力利用率下降，需在吞吐与尾延迟之间按 SLO 取舍。</p>\n<div class=\"formula\">$$T_{\\text{e2e}}=\\sum_{i}\\left(t^{\\text{queue}}_{i}+t^{\\text{compute}}_{i}\\right)+t_{\\text{fuse}},\\qquad \\text{tail}=\\max_{i}t^{\\text{queue}}_{i}$$</div>\n<p>具体例子：一批混合了长短片段，端到端时延超出 SLO 而单片段计算时延正常，分桶后尾延迟收敛，代价是短片段桶的批大小受限、吞吐略降。这一判断依赖监控同时采集排队与计算两段时延，只报总时延无法区分抖动与算力瓶颈。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-43\">四十三 · 静默降级：量化与融合接缝的无声失效</h3>\n<p>最危险的失败模式不报错。材料未给出 NVFP4/FP8 精度下的数值稳定性与显存收益数据，部署前需补量化验证；若未验证即上线，单步学生输出退化会以“画质略差”的形态出现，监控若只看时延与 OOM 完全无感。量化对单步生成尤其敏感，因为没有多步迭代的平均效应来掩盖舍入误差，潜变量的低位截断会直接放大为纹理崩坏或色彩偏移。诊断手段是把量化输出与高精度参考在同一初始噪声下逐片段比对，观察误差是否随分块长度与分辨率系统性增长。</p>\n<p>第二类静默降级在重叠融合：分块重叠区按权重融合，权重与片段顺序不匹配会在接缝处产生闪烁，单帧看正常，连续播放才暴露。监控应在融合前后各采一次接缝区域的帧差，接缝帧差显著高于片段内部帧差即判定融合异常。这类问题不会触发 OOM 或超时，却直接破坏长视频的连续性，属于必须在灰度阶段拦截的失败模式。</p>\n<ul><li>量化降级：漂移分数随分辨率档位单调上升，且高精度参考下不出现，判定为数值精度问题而非模型问题。</li><li>融合降级：接缝帧差与片段内部帧差之比越界，且与重叠权重配置相关，判定为融合参数问题。</li><li>两者共同点：时延、吞吐、显存指标全部正常，只有输出统计量能捕获。</li></ul>\n<p>代价在于诊断本身消耗算力：高精度参考路径与融合前后双采样都会增加显存与带宽占用，只能在抽样比例上控制，灰度期提高抽样率、稳态期降低。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-44\">四十四 · 回滚路径：按阶段与配置分层的最小回退</h3>\n<p>回滚不能只有“切回多步教师”一个档位，那会把采样步数从一步拉回数十步，吞吐与显存代价同时跳变。分阶段对抗蒸馏的结构提供了分层回退的抓手：阶段间共享学生权重并重置判别器，因此可以保留当前学生权重、只回退推理侧配置——先恢复分块长度与批大小的上一稳定组合，再回退量化档位，最后才考虑换回上一阶段的学生权重。回退顺序按影响面从小到大排列，避免一次动作同时改变数值精度与分块语义，导致无法归因。</p>\n<p>回滚触发条件应与诊断量绑定：漂移分数越阈值触发精度回退，显存高水位越档触发分块回退，接缝帧差比越界触发融合参数回退，尾延迟越 SLO 触发分桶与并发回退。每次回滚记录触发量、回退档位与回退后的同一指标，形成可复现的因果链。具体例子：某分辨率档位在 NVFP4 下漂移分数持续越界，回退到 FP8 后指标恢复，则判定为该档位的量化不稳定，而非学生权重退化，无需动训练侧。</p>\n<p>工程判断落在监控粒度上：分块融合接缝、显存峰值与片段时延是论文材料明确点出的三个监控对象，其余诊断量都是围绕它们做的扩展。容量规划只能按分块与批大小做保守估计，因为论文未给出数据集、FVD、吞吐与端到端时延数字；在没有实测的情况下，回滚阈值应设得偏紧，用灰度期的抽样诊断换取稳态期的稳定输出。单步学生的模式崩溃风险由分阶段收紧判别目标缓解，但推理侧无法观测训练期的均衡状态，因此线上只能以输出分布漂移作为代理信号，把回滚决策压在可测量的片段统计上。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-45\">四十五 · 分块接缝、显存峰值与量化退化：三类失效的定位与回滚</h3>\n<p>该方案把采样步数压到一步，代价从迭代采样转移到单次前向的激活与解码缓冲，因此失败模式也换了位置。最典型的静默降级不是数值报错，而是分块重叠融合的权重与片段顺序错配：接缝处出现闪烁或运动断裂，端到端视频看似正常返回，SLO 指标（片段时延）全绿。诊断上应把重叠区像素差与相邻片段潜变量的余弦相似度作为独立探针，按片段序号落盘，与分块长度、批大小一起进监控面板；一旦接缝指标越界，先回滚到上一版重叠权重与融合顺序，而不是调批。</p>\n<p>显存侧的失效是 OOM 与批抖动同源。分块长度直接决定单次前向的时空注意力激活峰值，批大小再乘上去；显存不足时调度器降并发或缩短分块，吞吐随批大小抖动，尾延迟被拉长。容量估算可用 <span class=\"formula\">$$M_{\\text{peak}} \\approx B\\cdot \\left(A_{\\text{st}}(L_f,L_r)+A_{\\text{vae}}\\right)$$</span> 做保守下界，其中 <span class=\"formula\">$$L_f,L_r$$</span> 为分块帧数与分辨率档位，<span class=\"formula\">$$A_{\\text{st}}$$</span> 为时空注意力激活、<span class=\"formula\">$$A_{\\text{vae}}$$</span> 为解码缓冲。B200/GB200 NVL72 档位上应按显存档位反推最大分块与并发，把“降批”与“缩短分块”做成两条独立回滚路径：前者保画质、后者保时延。</p>\n<p>精度塌陷发生在 NVFP4/FP8 未验证就上线的情形：单步学生没有多步迭代的误差摊薄，量化噪声直接进 VAE 解码，表现为细节糊化与色彩漂移，且不触发任何异常。监控应把量化前后同一初始噪声下的潜变量偏差、解码后片段亮度直方图偏移设为门禁，超阈值即回滚到高精度权重或关闭该档量化。分阶段对抗均衡本身对判别器强度敏感，阶段切换若与量化档位同时变更，故障归因会被掩盖——回滚粒度必须按“阶段配置 / 量化档 / 分块参数”三元组独立版本化。</p>\n<table class=\"mini\"><thead><tr><th>失效</th><th>可观测信号</th><th>首选回滚</th></tr></thead><tbody><tr><td>接缝闪烁</td><td>重叠区像素差、潜变量相似度</td><td>重叠权重与融合顺序</td></tr><tr><td>OOM/批抖动</td><td>显存峰值、批大小方差、尾延迟</td><td>缩短分块或降并发</td></tr><tr><td>量化退化</td><td>潜变量偏差、亮度直方图偏移</td><td>量化档位或高精度权重</td></tr></tbody></table>\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-46\">四十六 · 基准口径的三层结构：模型档、硬件档、负载档</h3>\n<p>读这篇论文的推理数字，先要把它拆成三层口径，任何一层没对齐，数字就不可比。第一层是模型档：教师是多步视频扩散或流匹配模型，学生是单步生成器，二者共享同一初始噪声分布才有意义；比较时必须声明是“学生单步 vs 教师 N 步”，而不是“学生单步 vs 另一篇论文的学生单步”。第二层是硬件档：B200/B300 单卡、GB200/GB300 NVL72 机柜是两种完全不同的显存与带宽形态，前者受单卡 HBM 容量与片内带宽约束，后者受 NVLink 5 域内聚合带宽与机柜功耗墙约束，同一份分块配置在两种档位上显存峰值与可承载并发不同。第三层是负载档：分辨率、帧数、分块长度、重叠帧数、批大小、并发请求数共同决定单次前向的激活规模。三层口径中任何一层缺失，横向对比就退化为定性叙述。</p>\n<p>论文材料本身没有给出数据集、FVD、吞吐与端到端时延数字，这意味着所有“提升”只能落在机制层面：采样步数从数十步降到一步，这是结构性的步数削减，可核验；而“吞吐提升多少倍”不可核验，因为单步前向的代价已经转移到时空注意力激活与 VAE 解码缓冲，这两块并不随步数线性缩小。工程上应把基准表写成三元组（模型档、硬件档、负载档）+ 指标集合，缺项标注“材料未给出”，而不是用别处的数字填充。</p>\n<div class=\"formula\">$$\\text{Speedup}_{\\text{wall}}=\\frac{T_{\\text{teacher}}(N_{\\text{steps}})}{T_{\\text{student}}(1)}=\\frac{N_{\\text{steps}}\\cdot t_{\\text{denoise}}}{t_{\\text{denoise}}+t_{\\text{attn-act}}+t_{\\text{vae}}}$$</div>\n<p>这个式子说明为什么“步数比”不等于“时延比”：当 $t_{\\text{vae}}$ 与 $t_{\\text{attn-act}}$ 在单步前向中占比上升时，分母被这两项主导，步数削减的收益被稀释。举例：一个 720p、121 帧的请求按带重叠时空片段切分，每片段单步前向的显存峰值由分块长度决定，VAE 解码缓冲按片段像素量分配；若把分块长度翻倍，注意力激活按片段内 token 数增长，显存峰值上升，批大小被迫下调，端到端时延未必改善。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-47\">四十七 · 指标集合：TTFT、TPOT、吞吐、显存、功耗各自度量什么</h3>\n<p>视频扩散的指标语义与 LLM 服务不同，必须重新定义。TTFT 在这里是“首片段可解码时延”：从请求进入到第一个时空片段完成单步前向并送入 VAE 解码的时间，包含分块切分、初始噪声构造与首片段前向。TPOT 不能直接套用 token 间隔，应改为“片段间隔时间”，即相邻片段完成前向并融合输出的时间差；对长视频流式输出，片段间隔决定播放端的缓冲深度。吞吐按“每秒完成解码的像素片段数”或“每秒成片秒数”计，两者不可混用，前者受前向与解码共同约束，后者还受重叠融合与封装开销影响。显存指标要区分峰值与稳态：峰值出现在单片段前向的时空注意力激活叠加 VAE 解码缓冲时刻，稳态由批内并发片段数决定。功耗指标在 NVL72 档位上按机柜功率墙折算，单卡功耗峰值不等于机柜可持续功耗。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>口径定义</th><th>主要受控因素</th><th>常见误读</th></tr></thead><tbody><tr><td>TTFT</td><td>首片段可解码时延</td><td>分块切分、首片段前向、VAE 首帧解码</td><td>与 LLM 首 token 时延直接类比</td></tr><tr><td>片段间隔</td><td>相邻片段输出时间差</td><td>批大小、并发、重叠融合</td><td>当作 TPOT 直接比较</td></tr><tr><td>吞吐</td><td>每秒解码片段数 / 每秒成片秒数</td><td>前向、VAE、融合、封装</td><td>两种口径混用</td></tr><tr><td>显存峰值</td><td>单片段前向 + 解码缓冲峰值</td><td>分块长度、批大小、精度</td><td>只看权重占用</td></tr><tr><td>功耗</td><td>机柜可持续功率折算</td><td>并发、SM 占用、内存带宽</td><td>用单卡峰值外推</td></tr></tbody></table>\n<p>具体例子：同一请求在 B200 单卡上以批大小 1、分块 16 帧运行，显存峰值由注意力激活主导；切到 GB200 NVL72 的一个计算托盘，NVLink 5 域内可把分块并行到多卡，单卡显存峰值下降但跨卡激活传输进入关键路径，片段间隔的瓶颈从显存转为通信。此时若只报“吞吐提升”，不报通信占比，数字不可比。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-48\">四十八 · 数字怎么读：四类不可比的“提升”</h3>\n<p>第一类不可比是步数比冒充时延比。论文的核心主张是单步前向替代多步采样，步数从数十降到一，这是算法层面的削减；但单步前向里时空注意力与 VAE 解码的代价不随步数缩小，所以墙钟时延的改善必须单独测量，材料未给出该测量。第二类不可比是分辨率与帧数不同的吞吐。片段数随帧数线性增长，像素量随分辨率平方增长，两个不同负载档的“每秒片段数”不能相除。第三类不可比是精度档不同。材料未给出 NVFP4/FP8 下的数值稳定性与显存收益数据，因此任何在 FP16 下测得的显存峰值都不能直接外推到 NVFP4 部署，量化后的激活缩放与反量化开销会改变峰值位置。第四类不可比是并发口径不同。批调度按片段长度与显存档位调整批大小，显存不足时降低并发或缩短分块；一个在高并发下测得的吞吐与一个在批大小 1 下测得的时延属于不同工作点，不能拼成一条曲线。</p>\n<ul>\n<li>步数削减是结构事实，可核验；时延与吞吐改善是待测项，材料未给出。</li>\n<li>分块长度改变显存峰值与批大小上限，跨配置的吞吐不可直接比较。</li>\n<li>量化档位未验证前，FP16 显存数字不能作为 NVFP4 容量规划依据。</li>\n<li>并发工作点必须与 SLO 绑定，脱开 SLO 的吞吐数字无工程意义。</li>\n</ul>\n<p>工程判断：把每个数字标注为“结构事实 / 待测 / 外推”三态。例如“采样步数从数十步降到一步”标结构事实；“单步学生逼近教师分布”标论文主张但缺 FVD；“NVFP4 下显存下降”标外推，需补验证。基准表里保留空列比填错数字更有价值。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-49\">四十九 · 容量规划的保守估计方法</h3>\n<p>材料未给出吞吐数字，容量规划只能按分块与批大小做保守估计。方法是从显存峰值反推并发上限：单片段前向的激活规模由分块内 token 数决定，VAE 解码缓冲由片段像素量决定，二者相加得到单片段峰值；用卡容量减去权重与运行时开销，得到可用余量，再除以单片段峰值得到理论并发片段数。批大小取该并发数与调度器上限的较小者。端到端时延按片段数乘以片段间隔估算，片段间隔取前向、解码、融合三段的上界之和。SLO 以片段生成时延与端到端视频时延双指标衡量，前者约束流式播放，后者约束成片交付。</p>\n<div class=\"formula\">$$N_{\\text{conc}}=\\left\\lfloor\\frac{M_{\\text{free}}}{M_{\\text{attn}}(L_{\\text{chunk}})+M_{\\text{vae}}(L_{\\text{chunk}})}\\right\\rfloor,\\quad T_{\\text{e2e}}\\approx N_{\\text{seg}}\\cdot\\left(t_{\\text{fwd}}+t_{\\text{vae}}+t_{\\text{fuse}}\\right)$$</div>\n<p>具体例子：长视频按帧数与分辨率切分为带重叠的时空片段，重叠区域按权重融合。若重叠帧数取分块长度的固定比例，片段数随帧数增长而增长，融合开销按重叠像素量计；缩短分块可降显存峰值、提并发，但片段数上升、融合接缝增多，端到端时延未必下降。这是容量规划里最典型的权衡点，必须用实测的片段间隔与融合开销校准，而不是用步数比推算。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-50\">五十 · 监控与失败模式对应的口径校验</h3>\n<p>三类失败模式直接对应三类口径错误。其一，把单步蒸馏收益等同于吞吐提升，忽略 VAE 解码与时空注意力激活的显存峰值——口径上表现为只报步数比、不报显存峰值与解码占比。其二，分块重叠融合不当在接缝处产生闪烁——口径上表现为吞吐按片段数计而融合质量未纳入指标，需按重叠权重与片段顺序校验，把接缝处的像素一致性作为附加指标。其三，未验证 NVFP4/FP8 数值稳定性即上线，单步学生输出退化——口径上表现为精度档未标注，需在部署前补量化验证与失败模式监控。监控项应包含：分块融合接缝指标、显存峰值时序、片段间隔分布、并发工作点与 SLO 达成率。</p>\n<p>论文的分阶段机制在推理侧不增加运行时开销：阶段间共享学生权重并重置判别器，属于训练期均衡手段；推理时只保留单步学生前向。因此基准表里不应把训练阶段的判别器开销计入推理时延，但应注明“分阶段训练增加训练开销”这一局限，避免读者把训练成本误读为推理成本。判别器均衡对超参敏感，阶段数与损失权重材料未给出，意味着复现时的基准必须在相同阶段配置下比较，跨配置的学生质量不可比。</p>\n<p>最终落在工程判断上：这篇论文可核验的是采样步数削减与分块重叠的部署路径，不可核验的是 FVD、吞吐与量化收益。基准表应以三元组口径为骨架，把每个数字标注三态，容量规划按显存峰值反推并发并以片段间隔校准端到端时延；在 NVFP4/FP8 数值稳定性与接缝质量监控补齐之前，任何跨档位的“提升”都不进入容量决策。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-51\">五十一 · 单步收益的边界：显存峰值、融合接缝与量化盲区</h3>\n<p>把采样步数从数十步压到一步，改变的是迭代次数，不是单次前向的代价结构。推理时显存峰值由分块长度与批大小共同决定：单步学生前向的激活量近似正比于片段帧数、分辨率与批大小的乘积，VAE 解码缓冲再叠加一层。设片段含 <em>F</em> 帧、分辨率 <em>H×W</em>、批大小 <em>B</em>，则单次前向的激活与解码缓冲可定性写为 <em>M</em> ≈ <em>B</em>·(<em>α</em>·<em>F</em>·<em>H</em>·<em>W</em> + <em>β</em>·<em>F</em>·<em>H</em>·<em>W</em>)，其中 <em>α</em> 对应时空注意力激活、<em>β</em> 对应 VAE 解码。步数下降只削减了与步数线性相关的部分，<em>α</em>、<em>β</em> 两项不随步数缩小。因此在 B200 单卡或 GB200 NVL72 单节点上，若分块长度不变而只改单步采样，显存峰值不会同比下降，吞吐提升受限于解码与注意力带宽，而非采样步数。</p>\n<p>分块重叠是第二个失效点。重叠区域按权重融合，权重与片段顺序必须一致；接缝闪烁来自重叠宽度不足或权重曲线在片段边界不连续。工程上应把重叠帧数作为独立超参，与分块长度解耦，并在融合后按片段序号校验边界帧的像素连续性。批调度按片段长度与显存档位调整批大小，显存不足时缩短分块或降并发——这条策略的代价是端到端时延随分块数增加而上升，流式输出按片段顺序返回，SLO 应以片段生成时延与整段视频时延两个口径分别度量，不能只报吞吐。</p>\n<table class=\"mini\"><thead><tr><th>口径</th><th>可比条件</th><th>不可比情形</th></tr></thead><tbody><tr><td>吞吐</td><td>同分块长度、同批大小、同分辨率</td><td>缩短分块换吞吐，接缝风险上升</td></tr><tr><td>显存峰值</td><td>同 VAE 解码缓冲配置</td><td>只报单步步数不报激活峰值</td></tr><tr><td>精度</td><td>同量化档位与同一失败模式监控</td><td>未验证 NVFP4/FP8 即对比 FVD</td></tr></tbody></table>\n<p>数字怎么读：论文未给出数据集、FVD、吞吐与端到端时延，容量规划只能按分块与批大小做保守估计。任何“单步即提速”的表述都必须附上分块长度、批大小、量化档位与显存峰值四项，否则与多步教师基线不可比。NVFP4/FP8 下单步学生的数值稳定性材料未给出，部署前需补量化验证，并监控分块融合接缝、显存峰值与片段时延三类失败信号；判别器均衡对超参敏感，阶段数与对抗权重缺失时，单步学生在复杂运动与长视频上的细节损失无法从现有材料判定。</p>\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-52\">五十二 · 迁移到非视频扩散主干：判别器语义先于权重迁移</h3>\n<p>把这套分阶段单步对抗均衡搬到别的生成主干上，第一件要改的不是超参，而是判别器的输入语义。论文的判别器比较的是学生单步输出与教师多步采样结果，二者处在同一潜空间、同一 VAE 解码口径下，对抗信号才有意义。若目标模型换成自回归视频生成或 LLM 解码器，教师与学生的“输出”不再是同一时刻的完整张量：自回归模型的教师是逐步条件分布，学生是少步近似，判别器若直接吃整段序列，会把条件依赖结构当成分布差异来惩罚，均衡点偏移。工程判断是：迁移时先固定“判别器看什么”——潜变量、解码后像素、还是 token 级分布——再谈阶段划分。判别器语义不确定，阶段收紧只会放大错误信号。</p>\n<p>公式层面，迁移后蒸馏项需要重写。原式中的 <span class=\"formula\">$$\\lambda\\,\\mathcal{L}_{\\text{distill}}\\left(G_{\\theta}(z),\\,G_{\\text{teacher}}(z)\\right)$$</span> 假设教师与学生共享同一初始噪声 <span class=\"formula\">$$z$$</span> 且输出可逐元素对齐。对自回归或编辑类模型，教师轨迹是多步条件链，学生单步前向没有对应的逐元素参照，蒸馏项必须改成轨迹级或分布级度量，例如对教师多步采样做统计矩匹配，而不是逐像素回归。这一步改错，对抗项与蒸馏项会互相拉扯，学生在强判别下退化。</p>\n<p>代价上，判别器语义变化直接改变显存结构。视频扩散里判别器吃的是潜变量片段，激活量与时空注意力同量级；换成 token 级判别器后，判别器自身的激活可能超过学生主干，显存峰值从“时空注意力 + VAE 解码缓冲”变成“判别器激活 + 学生激活”双峰。在 B200 单卡上这意味着分块长度要按判别器而非学生来定，批调度逻辑随之改写。具体例子：把方案迁到图像编辑模型时，若判别器按 patch 判别，编辑区域与未编辑区域的条件分布不同，判别器会把“未改动”误判为模式崩溃，阶段收紧后学生开始过度编辑——这是语义错配而非训练不稳。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-53\">五十三 · 跨领域迁移的改动清单：三个必须重设的量</h3>\n<p>迁到新领域时，有三个量必须重设，不能沿用视频扩散的默认值。第一是分块粒度。视频扩散按帧数与分辨率切带重叠时空片段，是因为时空注意力激活随帧数超线性增长；换到高分辨率图像或长文档生成，冗余结构不同，分块应跟随主导代价项——图像看 patch 数与注意力头维度，文档看序列长度与 KV 驻留。第二是重叠权重。视频接缝靠重叠融合消除闪烁，图像与文档没有时间连续性，重叠融合反而引入重复内容，应改为边界条件对齐或全局一致性约束。第三是阶段数与判别器强度曲线。论文材料未给出阶段数与权重，说明这套机制对超参敏感；跨领域时教师分布更窄或更宽，阶段收紧速度必须重估，否则单步学生在早期阶段就被强判别压成单一模式。</p>\n<p>伪代码思路可写成：对每个阶段 <span class=\"formula\">$$k$$</span>，固定判别器 <span class=\"formula\">$$D_k$$</span> 训练学生 <span class=\"formula\">$$G_\\theta$$</span> 若干步，然后重置 <span class=\"formula\">$$D$$</span> 并收紧其判别目标，学生权重跨阶段共享。迁移时唯一可复用的是“共享学生权重 + 重置判别器”这一骨架，其余全部重估。工程上建议把阶段收紧做成可观测的曲线：每阶段记录学生输出与教师输出的分布距离，距离不降就停，而不是按固定阶段数硬跑。</p>\n<p>代价判断：跨领域迁移的主要成本不在推理侧，而在训练侧的分阶段开销。视频扩散的教师多步采样本身昂贵，分阶段意味着教师轨迹要被反复生成；换到教师较便宜的领域（如小分辨率图像），分阶段训练开销可接受，换到教师更贵的领域（如长视频、高分辨率），阶段数必须压缩，否则训练成本超过推理节省。推理侧代价则取决于分块策略是否匹配新领域的主导显存项，匹配错则单步收益被分块开销吃掉。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-54\">五十四 · 哪里不适用：单步假设失效的边界</h3>\n<p>这套方案的核心假设是“教师多步轨迹可被单步前向近似”。该假设在两类场景下失效。第一类是强运动与长时序依赖：论文自身局限指出单步生成在复杂运动与长视频上可能损失细节，原因是单步前向没有迭代修正机会，运动连续性靠单次时空注意力一次性建模，误差无法在采样过程中回退。迁移到长视频或高动态场景时，分块重叠只能消除接缝闪烁，不能恢复块内运动细节，此时应保留少量步数（两步或三步）而非强推单步。第二类是条件分布多峰的场景：文本到视频的提示词歧义、编辑模型的多解空间，单步学生倾向于收敛到教师分布的某个模态，判别器在多阶段收紧后进一步压缩模态数，表现为“生成稳定但多样性塌缩”。这不是训练不稳，而是单步近似的固有边界。</p>\n<p>判断标准可以量化：若教师多步采样在相同初始噪声下的输出方差显著大于单步学生输出方差，说明单步近似丢掉了模态，此时分阶段对抗均衡无法补救，应退回少步而非单步。工程上可在部署前用小批量教师轨迹做方差对比，方差比超过阈值就不启用单步路径。代价上，退回少步意味着采样步数从一步回到数步，显存与带宽按步数线性回升，容量规划要按少步口径重算，不能沿用单步的批大小。</p>\n<p>另一个不适用点是量化精度未验证的场景。材料明确未给出 NVFP4/FP8 下的数值稳定性数据，而单步学生没有多步迭代的平均效应来平滑量化误差，一次前向的数值偏差直接进入 VAE 解码。在 Blackwell 上启用 NVFP4 前必须先做单步路径的数值验证，否则输出退化无法与模式崩溃区分。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-55\">五十五 · 规模上限：分块、批与显存三者的耦合约束</h3>\n<p>规模上限不由模型参数量决定，而由分块长度、批大小与显存峰值的耦合决定。单步前向把采样步数压到一步，显存主要来自时空注意力激活与 VAE 解码缓冲；分块长度直接决定单次前向激活峰值，批大小在显存档位内叠加。三者关系可写成约束：<span class=\"formula\">$$\\text{batch}\\times\\text{chunk\\_activation}+\\text{VAE\\_buffer}\\le\\text{VRAM\\_budget}$$</span>。当分块长度增加，激活按超线性上升，批大小必须下降；当批大小下降，吞吐按批维度损失，单步带来的步数收益被批缩小抵消。规模上限就出现在“分块不能再短、批不能再小”的交点：分块过短导致重叠比例上升，融合开销与接缝风险增加；批过小导致 GPU 利用率不足。</p>\n<p>在 GB200 NVL72 档位上，这个交点还受 NVLink 5 拓扑影响。若采用分离式预填/解码或跨节点并行，分块结果需要在节点间传输，带宽成为第二约束；单步前向的激活峰值虽低于多步累积，但分块融合的中间结果驻留会占用显存。工程判断是：规模上限应按“单卡可承受的最大分块 × 最小可用批”来估，而不是按理论峰值算力。具体例子：长视频请求按帧数切块，若单块激活已接近显存档位，批只能取一，此时吞吐由片段时延决定，流式输出按片段顺序返回，端到端时延等于片段数乘单片段时延，容量规划要按片段队列长度而非请求数建模。</p>\n<p>监控上要盯三个量：分块融合接缝、显存峰值、片段时延。显存不足时的降级路径是缩短分块或降低并发，二者都直接降低吞吐，因此规模上限本质是 SLO 与降级策略的折中点，不是硬件参数。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-56\">五十六 · 工程判断：迁移前先证明三件事</h3>\n<p>给出判断而非口号：这套方案迁到新模型或新领域前，必须先证明三件事，缺一件就不应上线。第一，判别器语义与教师学生输出口径一致，且判别器激活不成为新的显存峰值；第二，单步近似在该领域的输出方差比在可接受范围内，否则退回少步；第三，NVFP4/FP8 下单步路径的数值稳定性经过验证，输出退化可与模式崩溃区分。三件事都是定性可查的，不需要论文数字，但都需要部署方自己补测。</p>\n<p>可复用的部分只有骨架：分阶段共享学生权重、重置判别器、单步前向替代多步采样、分块重叠与批调度。不可复用的是超参、分块粒度、重叠权重与判别器输入语义。把可复用骨架当默认值直接迁移，是这类方案落地最常见的错误；论文材料未给出阶段数、损失权重与训练步数，本身就是信号——这些量必须按目标领域重估，而不是照搬。</p>\n<p>最后落在具体机制上：迁移的成败取决于分块长度与判别器激活的相对大小。若判别器激活小于学生时空注意力激活，分块策略可沿用视频扩散口径，只改重叠权重；若判别器激活更大，分块必须按判别器重设，批调度逻辑随之改写，规模上限随之下移。这个相对大小在部署前用一次前向的显存采样就能测出，是迁移决策里最便宜也最该先做的一步。</p>\n\n<h3 id=\"paper-phased-one-step-adversarial-equilibr-2025-sec-57\">五十七 · 迁移边界：单步学生换到别的模型要先改什么</h3>\n<p>这套方案的可迁移部分不是「单步」本身，而是「阶段间共享学生权重、重置判别器」的均衡节奏。迁到别的视频扩散或流匹配骨干时，必须重做的是判别器的输入域：教师与学生若不在同一潜空间（不同 VAE、不同 latent 通道数或时间压缩比），判别器无法在像素或潜变量上直接比较，需先把学生输出投影到教师潜空间再判别，否则对抗项退化为噪声。蒸馏项同样要改，<span class=\"formula\">$$\\mathcal{L}_{\\text{distill}}=\\mathbb{E}_{z}\\big\\|G_{\\theta}(z)-G_{\\text{teacher}}(z)\\big\\|_{2}^{2}$$</span>在单步对齐下只在相同初始噪声与相同条件嵌入时有意义，换骨干后条件编码器维度变化，须重新对齐文本/条件注入位置，否则学生学到的是条件错配的均值解。迁到图像扩散或 3D 生成时，时空注意力的时间轴退化为单帧或体素轴，分块重叠策略失效，方案退化为逐样本单步对抗蒸馏，收益仅剩步数压缩。</p>\n<p>失效条件集中在三类。其一是运动复杂度：单步前向没有迭代修正机会，快速运动与大位移场景下学生只能给出模糊的时间平均，重叠融合会在接缝处放大这种模糊，表现为闪烁而非细节丢失。其二是判别器强度与阶段数的耦合：阶段过少则单步学生在强对抗下模式崩溃，阶段过多则训练开销线性上升，而材料未给出阶段数与权重的可复现配置，迁移时只能按验证集 FVD 拐点自行搜索。其三是量化：NVFP4/FP8 下单步学生的输出分布更窄，判别器对量化噪声的敏感度高于多步采样，未做数值稳定性验证就上线会出现输出退化，这一项在容量规划里必须留出回退到 FP8 或 BF16 的显存档位。</p>\n<table class=\"mini\"><thead><tr><th>迁移对象</th><th>必改项</th><th>系统代价</th></tr></thead><tbody><tr><td>换 VAE/潜空间</td><td>判别器输入投影、蒸馏对齐</td><td>额外一次投影前向，显存峰值上升</td></tr><tr><td>换条件编码器</td><td>条件注入位置重对齐</td><td>需重训，阶段数增加</td></tr><tr><td>图像/3D 扩散</td><td>去掉时空分块与重叠融合</td><td>收益退化为纯步数压缩</td></tr><tr><td>NVFP4 部署</td><td>数值稳定性验证与回退档</td><td>保留高精度缓冲，挤占批大小</td></tr></tbody></table>\n<p>规模上限由分块长度与 VAE 解码缓冲共同决定，而非采样步数。单步把计算从数十次前向压到一次，但显存峰值仍由单片段时空注意力激活与解码缓冲占据，分块越长单次前向显存越高，批大小随之被压缩；在 B200/GB200 NVL72 档位上，容量规划应按「片段长度 × 批大小 × 解码缓冲」做保守估计，显存不足时优先缩短分块而非降精度，因为接缝闪烁的代价高于吞吐损失。判断标准很直接：若目标场景以长视频、复杂运动为主，且无 FVD 与端到端时延实测，这套方案只应作为步数压缩的候选而非默认路径；若场景是短片段、中等运动、可接受分块流式输出，则单步前向加重叠融合的收益成立，代价转移到解码缓冲与批调度。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Phased One-Step </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Adversarial Equilibrium…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2025 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Phased One-Step Adversa… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称</td></tr><tr><td>基线</td><td>多步教师采样、常规单步蒸馏基线</td></tr><tr><td>主要结果</td><td>论文主张分阶段单步对抗均衡在少步甚至单步采样下逼近教师分布，降低采样步数与…</td></tr><tr><td>消融</td><td>材料未给出消融实验细节，仅可推断阶段划分与对抗权重是主要变量。</td></tr><tr><td>局限</td><td>单步生成在复杂运动与长视频上可能损失细节，分阶段训练增加训练开销，判别器均…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-phased-one-step-adversarial-equilibr-2025 · 共 9 个片段</p>\n";break;}}})();
